      "content": "{\n  \"name\": \"dsh-taskboard\",\n  \"description\": \"Agent-first task board for the DSH web GUI: host-authoritative task ledger with taskboard_* agent tools, project (= workspace) claim boundaries, per-task model execution with optional existing-session reuse, optional per-task git-worktree isolation (dedicated task branches, commit evidence, one-click merge), host-side cron scheduling, and a live SSE kanban view. Mounts via the official dsh plugin system — no DSH source changes.\",\n  \"version\": \"0.9.11\",\n  \"type\": \"module\",\n  \"main\": \"lib/index.js\",\n  \"exports\": {\n    \".\": \"./lib/index.js\",\n    \"./invariant\": \"./lib/invariant.js\",\n    \"./client\": \"./lib/client.js\",\n    \"./package.json\": \"./package.json\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    },\n    \"client\": {\n      \"inject\": [\n        \"slots\"\n      ],\n      \"platform\": \"web\"\n    },\n    \"compatibility\": {\n      \"dshReleases\": {\n        \"0.2.0-rc.2\": \"compatible\"\n      }\n    }\n  },\n  \"files\": [\n    \"lib/**/*.js\",\n    \"lib/**/*.js.map\",\n    \"src\",\n    \"cordis.patch.yml\",\n    \"LICENSE\"\n  ],\n  \"license\": \"Apache-2.0\",\n  \"engines\": {\n    \"node\": \">=22\"\n  },\n  \"author\": \"cloader\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"git+https://github.com/cloader/dsh-taskboard.git\"\n  },\n  \"bugs\": {\n    \"url\": \"https://github.com/cloader/dsh-taskboard/issues\"\n  },\n  \"homepage\": \"https://github.com/cloader/dsh-taskboard#readme\",\n  \"keywords\": [\n    \"dsh\",\n    \"deepseek-harness\",\n    \"dsh-plugin\",\n    \"taskboard\",\n    \"kanban\",\n    \"agent\"\n  ],\n  \"scripts\": {\n    \"build\": \"tsdown -c tsdown.config.ts\",\n    \"build:host\": \"tsdown -c tsdown.host.config.ts\",\n    \"build:client\": \"tsdown -c tsdown.client.config.ts\",\n    \"watch\": \"tsdown -c tsdown.host.config.ts --watch\",\n    \"typecheck\": \"