    {
      "path": "src/host/external-config.ts",
      "content": "import type { ExternalConfig } from '../shared/external.ts'\nimport { newTaskId } from '../shared/protocol.ts'\nimport type { ExternalProviderRegistry } from './external-provider.ts'\n\n/** Platform-neutral validation; each registered provider validates its own scope/options. */\nexport function normalizeConnection(raw: unknown, registry: ExternalProviderRegistry, previous?: ExternalConfig, allowEmptyMappings = false, allowLegacyMappings = false): ExternalConfig {\n  if (!raw || typeof raw !== 'object') throw new Error('invalid external connection')\n  const e = raw as Record<string, unknown>\n  const provider = typeof e.provider === 'string' ? e.provider : previous?.provider ?? 'zentao'\n  const definition = registry.get(provider)\n  const descriptor = definition.descriptor\n  const mappingMode = provider === 'zentao' ? e.mappingMode : undefined\n  if (provider === 'zentao' && e.includeUnmapped !== undefined && typeof e.includeUnmapped !== 'boolean') throw new Error('invalid unmapped sync setting')\n  const includeUnmapped = provider === 'zentao' && e.includeUnmapped === true\n  const authMode = typeof e.authMode === 'string' ? e.authMode : descriptor.authModes[0]!.id\n  const mode = descriptor.authModes.find(m => m.id === authMode)\n  if (!mode) throw new Error('unsupported authentication mode')\n  const baseUrl = new URL(String(e.baseUrl ?? descriptor.defaultBaseUrl))\n  if (!['http:', 'https:'].includes(baseUrl.protocol) || baseUrl.username || baseUrl.password || baseUrl.search || baseUrl.hash) throw new Error('invalid server URL')\n  const url = baseUrl.href.replace(/\\/$/, '')\n  const account = typeof e.account === 'string' ? e.account.trim() : ''\n  if (!account) throw new Error('sync account is required')\n  const sameSource = previous?.provider === provider && previous.baseUrl === url && previous.account === account\n  const sameIdentity = sameSource && previous.authMode === authMode\n  const incoming = e.credentials && typeof e.credentials === 'object' && !Array.isArray(e.credentials) ? e.credentials as Record<string, unknown> : {}\n  const credentials: Record<string, string> = {}\n  for (const field of mode.fields) {\n    const value = incoming[field.key]\n    if (value !== undefined && typeof value !== 'string') throw new Error('invalid credential value')\n    const credential = typeof value === 'string' && value.length ? value : sameIdentity ? previous!.credentials[field.key] : ''\n    if (!credential) throw new Error('enter credentials for this server/account/authentication mode')\n    credentials[field.key] = credential\n  }\n  if (provider === 'zentao' && mappingMode !== 'project' && mappingMode !== 'execution'\n    && !(allowLegacyMappings && mappingMode === undefined)) throw new Error('select a project or execution mapping mode')\n  if (!Array.isArray(e.mappings)) throw new Error('at least one project mapping is required')\n  const mappings = e.mappings.filter((r: unknown) => provider !== 'zentao' || includeUnmapped || !r || typeof r !== 'object' || (r as Record<string, unknown>).workspaceId !== '').map((r: unknown) => {\n    if (!r || typeof r !== 'object') throw new Error('invalid mapping')\n    const m = r as Record<string, unknown>\n    if (typeof m.projectId !== 'string' || !m.projectId.trim() || typeof m.workspaceId !== 'string' || (!m.workspaceId && !includeUnmapped)) throw new Error('invalid mapping')\n    return { projectId: m.projectId.trim(), workspaceId: m.workspaceId }\n  })\n  if (!allowEmptyMappings && provider !== 'zentao' && !mappings.length) throw new Error('at least one project mapping is required')\n  if (new Set(mappings.map(m => m.projectId)).size !== mappings.length) throw new Error('duplicate project mapping')\n  const intervalMinutes = Number(e.intervalMinutes ?? 0)\n  const importStatus = e.importStatus ?? 'backlog'\n  if (importStatus !== 'backlog' && importStatus !== 'todo') throw new Error('import status must be backlog or todo')\n  if (!Number.isInteger(intervalMinutes) || (intervalMinutes !== 0 && (intervalMinutes < 5 || intervalMinutes > 1440))) throw new Error('sync interval must be 0 or 5–1440 minutes')\n  const since = String(e.since ?? '')\n  if (since && (!/^\\d{4}-\\d{2}-\\d{2}$/.test(since) || !Number.isFinite(Date.parse(since)) || new Date(since).toISOString().slice(0, 10) !== since)) throw new Error('invalid start date')\n  const itemTypes: string[] = e.itemTypes === undefined ? [descriptor.capabilities.itemTypes[0]!] : Array.isArray(e.itemTypes) ? e.itemTypes : []\n  if (!itemTypes.length || itemTypes.some(type => !descriptor.capabilities.itemTypes.includes(type))) throw new Error('unsupported or empty work item types')\n  const rawSettings = e.settings && typeof e.settings === 'object' ? e.settings as Record<string, unknown> : {}\n  const settings: Record<string, string> = {}\n  for (const field of descriptor.settingsFields ?? []) {\n    const value = rawSettings[field.key] ?? field.defaultValue\n    if (typeof value !== 'string') throw new Error('invalid provider setting')\n    settings[field.key] = value.trim()\n  }\n  const config: ExternalConfig = { id: sameSource ? previous!.id : newTaskId(), provider, baseUrl: url, account, authMode,\n    credentials, itemTypes: [...new Set(itemTypes)], settings, mappings, intervalMinutes, since, importStatus,\n    ...(mappingMode === 'project' || mappingMode === 'execution' ? { mappingMode, includeUnmapped } : {}) }\n  definition.validate?.(config)\n  return config\n}\n"
    },
    {
      "path": "src/host/external-http.ts",
      "content": "/** Shared bounded read-only HTTP transport. Never includes server bodies/credentials in errors. */\nexport async function externalGet(request: typeof fetch, url: string, headers: Record<string, string>, signal: AbortSignal, beforeRequest?: () => Promise<void>): Promise<unknown> {\n  for (let attempt = 0; ; attempt++) {\n    signal.throwIfAborted()\n    await beforeRequest?.()\n    const response = await request(url, { headers: { ...headers, Accept: 'application/json' }, signal: AbortSignal.any([signal, AbortSignal.timeout(30_000)]), redirect: 'error' })\n    if ((response.status === 429 || response.status >= 500) && attempt < 2) {\n      const retry = response.headers.get('retry-after')\n      const seconds = retry && /^\\d+$/.test(retry) ? Math.min(Number(retry), 30) : 2 ** attempt\n      await response.body?.cancel()\n      await new Promise<void>((resolve, reject) => {\n        const onAbort = () => { clearTimeout(timer); reject(new Error('request aborted')) }\n        const timer = setTimeout(() => { signal.removeEventListener('abort', onAbort); resolve() }, seconds * 1000)\n        signal.addEventListener('abort', onAbort, { once: true })\n        if (signal.aborted) onAbort()\n      })\n      continue\n    }\n    if (!response.ok) throw new Error(`External request failed (HTTP ${response.status})`)\n    try { return await response.json() }\n    catch { throw new Error('External service returned invalid JSON') }\n  }\n}\n\n/** Reserve slots before waiting so overlapping requests also observe the minimum interval. */\nexport class ExternalRequestThrottle {\n  private nextAt = 0\n  constructor(private readonly intervalMs: number) {}\n  async wait(signal: AbortSignal): Promise<void> {\n    signal.throwIfAborted()\n    const now = Date.now(); const at = Math.max(now, this.nextAt)\n    this.nextAt = at + this.intervalMs\n    if (at <= now) return\n    await new Promise<void>((resolve, reject) => {\n      const abort = () => { clearTimeout(timer); reject(new Error('request aborted')) }\n      const timer = setTimeout(() => { signal.removeEventListener('abort', abort); resolve() }, at - now)\n      signal.addEventListener('abort', abort, { once: true }); if (signal.aborted) abort()\n    })\n  }\n}\n\nexport function trackerText(raw: unknown): string {\n  return String(raw ?? '').replace(/<(script|style)\\b[^>]*>[\\s\\S]*?<\\/\\1>/gi, '')\n    .replace(/<\\s*(br\\s*\\/?|\\/p|\\/div|\\/li)\\s*>/gi, '\\n').replace(/<[^>]*>/g, '')\n    .replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&amp;/g, '&')\n    .replace(/&quot;/g, '\"').replace(/&#39;/g, \"'\").trim()\n}\n"
    },
    {
      "path": "src/host/external-sync.ts",
      "content": "import { mkdir, readFile, rename, writeFile } from 'node:fs/promises'\nimport { dirname } from 'node:path'\nimport type { ExternalItem, ExternalSource, ExternalSyncRecord } from '../shared/external.ts'\nimport { externalKey, mergeExternalFields, normalizeExternalSource, normalizeExternalSyncRecords } from '../shared/external.ts'\nimport { defaultIsolationOf, defaultPermissionOf, newTaskId, normalizeTitle, type TaskRecord, type TaskLedger } from '../shared/protocol.ts'\nimport type { TaskStore } from './store.ts'\nimport type { ExternalConfig, ExternalSyncStatus, SyncResult } from '../shared/external.ts'\nimport type { ExternalTaskProvider, ExternalProviderRegistry } from './external-provider.ts'\nimport { createBuiltinProviders } from './external-providers.ts'\nimport { normalizeConnection } from './external-config.ts'\nexport type { ExternalConfig, SyncResult } from '../shared/external.ts'\nexport type { ExternalTaskProvider } from './external-provider.ts'\n\ntype SyncState = { config?: ExternalConfig }\n\nexport function normalizeExternalConfig(raw: unknown, previous?: ExternalConfig): ExternalConfig {\n  return normalizeConnection(raw, createBuiltinProviders(), previous)\n}\n\n/** Host-only connection state. Credential files live outside task exports. */\nexport class ExternalSyncService {\n  private state: SyncState = {}\n  private volatileError?: string\n  private ready: Promise<void>\n  private lane: Promise<unknown> = Promise.resolve()\n  private running = false\n  private disposed = false\n  private controller?: AbortController\n  private timer?: ReturnType<typeof setInterval>\n  private lastAttempt = 0\n  private readonly registry: ExternalProviderRegistry\n  constructor(private readonly options: {\n    file: string; store: TaskStore; workspaceExists: (id: string) => boolean\n    provider?: (config: ExternalConfig) => ExternalTaskProvider; now?: () => number; registry?: ExternalProviderRegistry\n  }) {\n    this.registry = options.registry ?? createBuiltinProviders()\n    this.ready = this.load()\n    // Construction is eager, before callers await ready. Keep the rejection\n    // for request guards without letting a damaged ledger terminate the host.\n    void this.ready.catch(error => {\n      console.warn('[dsh-taskboard] external sync initialization failed; ledger retained:', error)\n    })\n  }\n  private now(): number { return this.options.now?.() ?? Date.now() }\n  private async load(): Promise<void> {\n    try {\n      const raw = JSON.parse(await readFile(this.options.file, 'utf8')) as SyncState & Partial<ExternalSyncRecord>\n      if (raw.config) {\n        if (typeof raw.config.id !== 'string' || !raw.config.id) throw new Error('invalid connection identity')\n        this.state.config = { ...normalizeConnection(raw.config, this.registry, undefined, false, true), id: raw.config.id }\n      }\n      await this.options.store.load()\n      // Move existing non-secret metadata once; token-only authentication is still rejected above.\n      if (this.state.config && (Object.keys(raw.links ?? {}).length || raw.ignored?.length || raw.lastResult || raw.lastError)) {\n        const id = this.state.config.id\n        const migrated = normalizeExternalSyncRecords({ [id]: raw })[id]!\n        await this.options.store.mutate('external-sync-updated', ledger => {\n          if (ledger.externalSync?.[id]) return undefined\n          ledger.externalSync ??= {}; ledger.externalSync[id] = migrated\n          return []\n        })\n      }\n      this.lastAttempt = this.state.config ? this.options.store.snapshot().externalSync?.[this.state.config.id]?.lastAttemptAt ?? 0 : 0\n    } catch (error) {\n      if ((error as NodeJS.ErrnoException).code !== 'ENOENT') this.volatileError = 'External sync configuration could not be loaded; reconfigure the connection.'\n    }\n    await this.options.store.load()\n  }\n  private async persist(): Promise<void> {\n    await mkdir(dirname(this.options.file), { recursive: true })\n    const temp = `${this.options.file}.tmp`\n    await writeFile(temp, JSON.stringify(this.state), { mode: 0o600 })\n    await rename(temp, this.options.file)\n  }\n  private serial<T>(run: () => Promise<T>): Promise<T> {\n    const next = this.lane.then(run, run)\n    this.lane = next.catch(() => {})\n    return next\n  }\n  async status(): Promise<ExternalSyncStatus> {\n    await this.ready\n    const config = this.state.config ? (({ credentials: _credentials, ...rest }) => rest)(this.state.config) : undefined\n    const credentialPresent = Object.fromEntries(Object.entries(this.state.config?.credentials ?? {}).map(([key, value]) => [key, Boolean(value)]))\n    const mode = config && this.registry.get(config.provider).descriptor.authModes.find(m => m.id === config.authMode)\n    const credentialValues = Object.fromEntries((mode?.fields ?? []).filter(f => f.secret === false).map(f => [f.key, this.state.config!.credentials[f.key] ?? '']))\n    const record = config ? this.options.store.snapshot().externalSync?.[config.id] : undefined\n    return { config, credentialPresent, credentialValues, providers: this.registry.list(), running: this.running,\n      requiresMappingReview: config?.provider === 'zentao' && !config.mappingMode,\n      lastResult: record?.lastResult, lastError: this.volatileError ?? record?.lastError, lastAttemptAt: record?.lastAttemptAt, ignoredCount: record?.ignored.length ?? 0 }\n  }\n  async configure(raw: unknown): Promise<void> {\n    await this.ready\n    if (this.running) throw new Error('sync is running')\n    await this.serial(async () => {\n      if (this.running) throw new Error('sync is running')\n      const config = normalizeConnection(raw, this.registry, this.state.config)\n      if (config.mappings.some(m => m.workspaceId ? !this.options.workspaceExists(m.workspaceId) : !config.includeUnmapped)) throw new Error('unknown workspace')\n      const old = this.state\n      this.state = { config }\n      try { await this.persist() } catch (e) { this.state = old; throw e }\n      this.volatileError = undefined\n    })\n  }\n  async clearIgnored(): Promise<void> {\n    await this.ready\n    if (this.running) throw new Error('sync is running')\n    await this.serial(async () => {\n      if (this.running) throw new Error('sync is running')\n      if (!this.state.config) throw new Error('configure a connection first')\n      await this.options.store.mutate('external-sync-updated', ledger => {\n        const record = this.record(ledger, this.state.config!.id)\n        record.ignored = []; record.links = {}\n        return []\n      })\n    })\n  }\n  async resolve(taskId: string, field: string, acceptExternal: boolean, ifVersion: number): Promise<void> {\n    if (!['title', 'description', 'urgency'].includes(field)) throw new Error('invalid conflict field')\n    await this.options.store.mutate('task-updated', ledger => {\n      const task = ledger.tasks.find(t => t.id === taskId)\n      if (!task?.external || task.version !== ifVersion) throw new Error('task changed; refresh and retry')\n      if (task.status === 'in_progress' || task.executions.some(e => e.outcome === 'running')) throw new Error('wait until execution finishes')\n      const key = field as 'title' | 'description' | 'urgency'\n      if (!task.external.conflicts.includes(key)) throw new Error('field is not an unresolved conflict')\n      if (acceptExternal) {\n        if (key === 'urgency') task.urgency = task.external.item.urgency\n        else task[key] = task.external.item[key]\n      }\n      task.external.conflicts = task.external.conflicts.filter(k => k !== key)\n      task.version++; task.updatedAt = this.now(); task.updatedBy = { kind: 'user' }\n      return [task]\n    })\n  }\n  private record(ledger: TaskLedger, connectionId: string): ExternalSyncRecord {\n    ledger.externalSync ??= {}\n    return ledger.externalSync[connectionId] ??= { links: {}, ignored: [] }\n  }\n  start(): void {\n    if (this.timer || this.disposed) return\n    this.timer = setInterval(() => { void this.tick().catch(() => {}) }, 30_000)\n    this.timer.unref?.()\n  }\n  private async tick(): Promise<void> {\n    await this.ready\n    const interval = this.state.config?.intervalMinutes ?? 0\n    if (this.state.config?.provider === 'zentao' && !this.state.config.mappingMode) return\n    if (interval && !this.running && this.now() - this.lastAttempt >= interval * 60_000) await this.sync()\n  }\n  dispose(): void { this.disposed = true; if (this.timer) clearInterval(this.timer); this.controller?.abort() }\n  cancel(): void { this.controller?.abort() }\n  async test(raw?: unknown): Promise<void> {\n    await this.ready\n    const config = raw ? normalizeConnection(raw, this.registry, this.state.config, true) : this.state.config\n    if (!config) throw new Error('configure a connection first')\n    await this.provider(config).test(AbortSignal.timeout(30_000))\n  }\n  private provider(config: ExternalConfig): ExternalTaskProvider { return this.options.provider?.(config) ?? this.registry.create(config) }\n  async discoverProjects(raw?: unknown) {\n    await this.ready\n    const config = raw ? normalizeConnection(raw, this.registry, this.state.config, true) : this.state.config\n    if (!config) throw new Error('configure a connection first')\n    const descriptor = this.registry.get(config.provider).descriptor\n    const provider = this.provider(config)\n    if (!descriptor.capabilities.projectDiscovery || !provider.listProjects) throw new Error('project discovery is not supported')\n    return provider.listProjects(AbortSignal.timeout(30_000))\n  }\n  async discoverAccount() {\n    await this.ready\n    if (!this.state.config) throw new Error('configure a connection first')\n    const definition = this.registry.get(this.state.config.provider)\n    const provider = this.provider(this.state.config)\n    if (!definition.descriptor.capabilities.accountDiscovery || !provider.getAccount) throw new Error('this provider requires an explicit assignee account')\n    return provider.getAccount(AbortSignal.timeout(30_000))\n  }\n  async sync(): Promise<SyncResult> {\n    await this.ready\n    if (this.disposed) throw new Error('sync service stopped')\n    if (this.running) throw new Error('sync is already running')\n    if (!this.state.config) throw new Error('configure a connection first')\n    if (this.state.config.provider === 'zentao' && !this.state.config.mappingMode) throw new Error('reassociate projects or executions before synchronizing')\n    this.running = true\n    this.lastAttempt = this.now()\n    const config = structuredClone(this.state.config)\n    this.controller = new AbortController()\n    const signal = AbortSignal.any([this.controller.signal, AbortSignal.timeout(300_000)])\n    const result: SyncResult = { created: 0, updated: 0, unchanged: 0, conflicts: 0, ignored: 0, at: this.now() }\n    let committed = false\n    try {\n      await this.options.store.load()\n      const provider = this.provider(config)\n      let mappings = config.mappings\n      if (config.provider === 'zentao' && config.includeUnmapped) {\n        if (!provider.listProjects) throw new Error('scope discovery is required for unmapped synchronization')\n        const scopes = await provider.listProjects(signal)\n        const associated = new Map(config.mappings.filter(m => m.workspaceId).map(m => [m.projectId, m]))\n        for (const scope of scopes) {\n          if (!new RegExp(`^${config.mappingMode}:\\\\d+$`).test(scope.id)) throw new Error('provider returned an unexpected mapping scope')\n          if (!associated.has(scope.id)) associated.set(scope.id, { projectId: scope.id, workspaceId: '' })\n        }\n        mappings = [...associated.values()]\n      }\n      // Finish all pages before committing: a failed scan never infers deletion or advances state.\n      const items: Array<{ item: ExternalItem; workspaceId: string }> = []\n      for (const mapping of mappings) {\n        if (mapping.workspaceId && !this.options.workspaceExists(mapping.workspaceId)) throw new Error('mapped workspace no longer exists')\n        const existing = new Map(this.options.store.snapshot().tasks.filter(t => t.external?.connectionId === config.id && t.external.item.projectId === mapping.projectId)\n          .map(t => [JSON.stringify([t.external!.item.type, t.external!.item.id]), { item: t.external!.item, metadataOnly: t.trashedAt !== undefined || ['done', 'canceled', 'archived'].includes(t.status) }]))\n        for (const item of await provider.getItems(mapping.projectId, signal, { existing })) {\n          if (item.projectId !== mapping.projectId || !config.itemTypes.includes(item.type)) throw new Error('provider returned an unexpected scope or work item type')\n          const source = normalizeExternalSource({ connectionId: config.id, provider: config.provider, item, syncedAt: result.at, conflicts: [] })\n          if (!source) throw new Error('provider returned an invalid work item')\n          items.push({ item: source.item, workspaceId: mapping.workspaceId })\n        }\n      }\n      signal.throwIfAborted()\n      await this.serial(async () => {\n        signal.throwIfAborted()\n        await this.options.store.mutate('external-sync-updated', ledger => {\n          signal.throwIfAborted()\n          const record = this.record(ledger, config.id)\n          const ignored = new Set(record.ignored)\n          const links = { ...record.links }\n          const changed: TaskRecord[] = []\n          const byKey = new Map(ledger.tasks.filter(t => t.external).map(t => [externalKey(t.external!.connectionId, t.external!.item), t]))\n          const seen = new Set<string>()\n          for (const { item: rawItem, workspaceId } of items) {\n            const item = { ...rawItem, title: normalizeTitle(rawItem.title) }\n            const key = externalKey(config.id, item)\n            if (seen.has(key)) continue\n            seen.add(key)\n            const task = byKey.get(key)\n            if (task) links[key] = task.id\n            if (!task && links[key]) ignored.add(key)\n            if (task?.trashedAt !== undefined) { ignored.add(key); result.ignored++; continue }\n            if (ignored.has(key)) { result.ignored++; continue }\n            if (task?.status === 'archived') { result.unchanged++; continue }\n            const source: ExternalSource = { connectionId: config.id, provider: config.provider, providerName: this.registry.get(config.provider).descriptor.name, item, syncedAt: result.at, conflicts: [] }\n            if (!task) {\n              if (item.closed || !(item.assignees ?? [item.assignedTo]).includes(config.account)) continue\n              const created: TaskRecord = { id: newTaskId(), title: item.title, description: item.description, urgency: item.urgency,\n                workspaceId, prompt: '', status: config.importStatus ?? 'backlog', blocked: false, execution: { mode: 'claim' },\n                isolation: defaultIsolationOf(ledger.settings), permission: defaultPermissionOf(ledger.settings),\n                model: ledger.settings?.defaultModel, presetId: ledger.settings?.defaultPresetId,\n                version: 1, createdAt: result.at, updatedAt: result.at, createdBy: { kind: 'user' }, updatedBy: { kind: 'user' },\n                comments: [], executions: [], external: source }\n              ledger.tasks.push(created); changed.push(created); byKey.set(key, created); links[key] = created.id; result.created++\n            } else {\n              links[key] = task.id\n              const workspaceChanged = config.provider === 'zentao' && task.workspaceId === '' && workspaceId !== ''\n              if (workspaceChanged) task.workspaceId = workspaceId\n              if (task.status === 'done' || task.status === 'canceled') {\n                const old = task.external!.item\n                const statusChanged = ['status', 'assignedTo', 'assignees', 'closed'].some(key => JSON.stringify(old[key as keyof ExternalItem]) !== JSON.stringify(item[key as keyof ExternalItem]))\n                if (!workspaceChanged && !statusChanged && !task.external!.conflicts.length) { result.unchanged++; continue }\n                task.external = { ...task.external!, item: { ...old, status: item.status, assignedTo: item.assignedTo, closed: item.closed,\n                  ...(item.assignees !== undefined ? { assignees: item.assignees } : {}) }, conflicts: [], syncedAt: result.at }\n                if (item.assignees === undefined) delete task.external.item.assignees\n                task.version++; task.updatedAt = result.at\n                changed.push(task); result.updated++\n                continue\n              }\n              const merged = mergeExternalFields(task, task.external!, item,\n                ['in_progress', 'in_review'].includes(task.status) || task.executions.some(e => e.outcome === 'running'))\n              source.conflicts = merged.conflicts\n              const previous = task.external!.item\n              const sameItem = ([...new Set([...Object.keys(previous), ...Object.keys(item)])] as Array<keyof ExternalItem>).every(key => JSON.stringify(previous[key]) === JSON.stringify(item[key]))\n              if (!workspaceChanged && sameItem && JSON.stringify(task.external!.conflicts) === JSON.stringify(source.conflicts)) { result.unchanged++; continue }\n              Object.assign(task, merged.fields)\n              task.external = source; task.version++; task.updatedAt = result.at\n              changed.push(task); result.updated++\n              if (source.conflicts.length) result.conflicts++\n            }\n          }\n          record.ignored = [...ignored]; record.links = links; record.lastResult = result\n          record.lastAttemptAt = this.lastAttempt; delete record.lastError\n          return changed\n        })\n        committed = true\n        this.volatileError = undefined\n      })\n      return result\n    } catch (error) {\n      // Never expose server bodies or request URLs (which may contain credentials).\n      const message = committed ? 'Tasks were updated, but sync completion reporting failed.' : 'External sync failed. Check connection, credentials, permissions and server availability.'\n      this.volatileError = message\n      try {\n        await this.serial(async () => this.options.store.mutate('external-sync-updated', ledger => {\n          const record = this.record(ledger, config.id)\n          record.lastAttemptAt = this.lastAttempt; record.lastError = message\n          return []\n        }))\n      } catch { this.volatileError = `${message} Sync status could not be saved.` }\n      throw new Error(this.volatileError, { cause: error })\n    } finally { this.running = false; this.controller = undefined }\n  }\n}\n"
    },
    {
      "path": "src/host/git.ts",
      "content": "/**\n * Host git face (0.3.0): the ONLY place dsh-taskboard shells out to git.\n * 0.3.1: per-repo serialization of structural operations, binary probing,\n * no-op merge detection, worktree REUSE mode, and evidence size caps.\n *\n * Design invariants (plan §3.4/§3.5):\n * - NARROW interface: detect / binaryAvailable / prepareWorktree / collect /\n *   merge / isAncestor / removeWorktree / deleteBranch — nothing else leaks\n *   into the plugin.\n * - FAIL-SOFT: every call has a timeout and resolves to a benign result\n *   (false / undefined / empty facts) on ANY git failure — a missing git,\n *   a locked worktree, or a damaged repo degrades execution to the original\n *   directory and NEVER fails the ledger or the run pipeline. Only the\n *   explicit user actions (merge / remove / deleteBranch) throw, with a\n *   readable message the GUI surfaces as-is.\n * - SERIALIZED structural ops: concurrent isolated executions on the SAME\n *   repository would race on git's index/worktree locks, so every structural\n *   operation (prepareWorktree / merge / removeWorktree / deleteBranch) runs\n *   inside a per-root in-process mutex. Read-only collects stay concurrent.\n * - INJECTABLE runner: the exec layer is a single function so unit tests\n *   script every path without a real git.\n *\n * @module dsh-taskboard/host/git\n */\nimport { resolve } from 'node:path'\nimport { buildBranchName, DEFAULT_BRANCH_NAME_MODE, DEFAULT_BRANCH_NAME_PREFIX, isValidTaskId, type CommitInfo } from '../shared/protocol.ts'\n\n/** Timeout for quick read-only queries (rev-parse / status / log / diff). */\nconst QUICK_TIMEOUT_MS = 2_000\n\n/** Timeout for structural operations (worktree add/remove, merge, branch). */\nconst HEAVY_TIMEOUT_MS = 15_000\n\n/** Directory under a workspace where task worktrees live. */\nexport const WORKTREE_DIR = '.dsh-worktrees'\n\n/**\n * The path segment of one `status --porcelain` line. Shape-aware: the RAW\n * line is `XY path` (path at index 3) while the plugin's trimmed evidence\n * lines collapse a leading-space status to `X path` (path at index 2) —\n * slicing a fixed 3 misparses exactly the gitlink/unstaged shapes a\n * multi-repo mirror produces (` M sub-repo`), 0.6.3 review fix.\n */\nexport function statusLinePath(line: string): string {\n  if (line.length >= 3 && line[2] === ' ') return line.slice(3)\n  if (line.length >= 2 && line[1] === ' ') return line.slice(2)\n  return line\n}\n\n/**\n * Whether a `status --porcelain` line targets one of `rels` (a repo-relative\n * path) or anything under it. Porcelain prints untracked directories with a\n * trailing slash (`?? sub/`), so all three shapes match. Empty rels never\n * match (0.6.3 review fix).\n */\nexport function statusLineUnder(line: string, rels: readonly string[]): boolean {\n  const p = statusLinePath(line)\n  return rels.some(rel => rel.length > 0 && (p === rel || p === rel + '/' || p.startsWith(rel + '/')))\n}\n\n/** Evidence caps: commits kept per execution record (newest first). */\nexport const MAX_COMMIT_EVIDENCE = 50\n\n/** Evidence caps: uncommitted-change lines kept per execution record. */\nexport const MAX_DIRTY_EVIDENCE = 100\n\n/** Diff viewer caps (0.4.0): raw text kept per view. */\nexport const MAX_DIFF_BYTES = 128 * 1024\n\n/** Diff viewer caps: lines kept per view. */\nexport const MAX_DIFF_LINES = 2_000\n\n/** One capped, read-only diff view (diff viewer, 0.4.0). */\nexport interface DiffResult {\n  text: string\n  truncated: boolean\n}\n\n/** Cap one diff payload by bytes and lines (in order, marking truncation). */\nfunction capDiff(out: string): DiffResult {\n  let text = out\n  let truncated = false\n  if (text.length > MAX_DIFF_BYTES) {\n    text = text.slice(0, MAX_DIFF_BYTES)\n    truncated = true\n  }\n  const lines = text.split('\\n')\n  if (lines.length > MAX_DIFF_LINES) {\n    text = lines.slice(0, MAX_DIFF_LINES).join('\\n')\n    truncated = true\n  }\n  return { text, truncated }\n}\n\n/** A plausible git object hash (defense against option injection). */\nfunction isHash(hash: string): boolean {\n  return /^[0-9a-f]{4,64}$/i.test(hash)\n}\n\n/** Result of one underlying exec: `ok` is exit-0, output never null. */\nexport interface ExecResult { ok: boolean; stdout: string; stderr: string }\n\n/** The injectable exec layer: run `git <args>` under a cwd with a timeout. */\nexport type ExecFn = (args: string[], options: { cwd?: string; timeout?: number }) => Promise<ExecResult>\n\n/** Unknown status must never authorize worktree or filesystem deletion. */\nexport function worktreeStatusError(path: string, cause?: unknown): Error & { code: string } {\n  return Object.assign(new Error(`Cannot verify worktree status; refusing to delete: ${path}`, { cause }), {\n    code: 'worktree-status-unavailable',\n  })\n}\n\n/** Facts needed to open an isolated execution. */\nexport interface WorktreeInfo {\n  /** Absolute worktree path (the session's cwd). */\n  path: string\n  /** The task branch checked out there. */\n  branch: string\n  /** Baseline for evidence collection: main HEAD (fresh) or worktree HEAD (reuse). */\n  baseCommit: string\n  /** True when an existing live worktree was kept as-is (续跑). */\n  reused?: boolean\n}\n\n/** Settlement facts collected from a worktree (partial on best-effort basis). */\nexport interface SettlementFacts {\n  headCommit?: string\n  commits: CommitInfo[]\n  /** Total commits before capping (equals commits.length when under the cap). */\n  commitsTotal: number\n  dirtyFiles: string[]\n  /** Total uncommitted lines before capping. */\n  dirtyFilesTotal: number\n  diffStat?: string\n  changedFiles: number\n}\n\n/** The narrow git face the rest of the plugin depends on. */\nexport interface GitFace {\n  /** Whether `root` sits inside a usable git work tree (fail-soft → false). */\n  detect(root: string): Promise<boolean>\n  /** Whether a usable git binary answers at all (distinguishes 未装 git vs 非 git 仓库). */\n  binaryAvailable(): Promise<boolean>\n  /**\n   * Ensure a worktree at `path` on `branch`. Default mode `'fresh'` resets to\n   * the main worktree's current HEAD (每次全新); mode `'reuse'` keeps a live\n   * worktree exactly as-is (续跑 — agent's commits and uncommitted changes\n   * survive) and falls back to a fresh creation when none is alive. Resolves\n   * undefined on any failure — callers degrade to the original directory.\n   */\n  prepareWorktree(root: string, path: string, branch: string, mode?: 'fresh' | 'reuse'): Promise<WorktreeInfo | undefined>\n  /**\n   * Collect settlement facts (never throws; missing pieces stay unset).\n   * `excludeRelPaths` drops `status --porcelain` lines targeting those\n   * repo-relative paths (or anything under them) — the mirror's NESTED repo\n   * worktrees read as untracked noise in the root worktree's status and are\n   * not this repo's uncommitted changes (0.6.3 review fix).\n   */\n  collect(worktreePath: string, baseCommit: string, excludeRelPaths?: readonly string[]): Promise<SettlementFacts>\n  /**\n   * Uncommitted-change lines of a working tree ([] = clean; undefined on git\n   * failure or when cwd is not the worktree root). Undefined is UNKNOWN,\n   * never clean: destructive callers must refuse it.\n   */\n  dirtyLines(cwd: string): Promise<string[] | undefined>\n  /**\n   * Merge `branch` into the main worktree (`--no-ff`); THROWS with a readable\n   * reason. `exemptRelPaths` extends the main-clean exemption beyond\n   * `.dsh-worktrees`: uncommitted-shape noise under those repo-relative paths\n   * (parallel repos are self-governing — their content AND their gitlink\n   * entries don't gate the root repo's merge, 0.6.3 review fix).\n   */\n  merge(root: string, branch: string, exemptRelPaths?: readonly string[]): Promise<void>\n  /** Whether `branch` is already an ancestor of HEAD (a merge would be a no-op). */\n  isAncestor(root: string, branch: string): Promise<boolean>\n  /**\n   * Remove a worktree. Resolves 'removed' on success, 'unregistered' when git\n   * no longer knows the path (an orphaned directory). THROWS when it still\n   * has uncommitted changes, or on any other git failure (readable reason).\n   * `opts.exempt` drops mirror-structural noise from the dirty check and\n   * `opts.force` lets `git worktree remove` accept it — for callers that have\n   * ALREADY aggregated the real-dirty check themselves (the mirror removal:\n   * noise-exempt clean → force is safe; real dirt never gets here).\n   */\n  removeWorktree(root: string, worktreePath: string, opts?: { exempt?: readonly string[]; force?: boolean }): Promise<'removed' | 'unregistered'>\n  /** Delete a branch; THROWS (e.g. still checked out in a worktree). */\n  deleteBranch(root: string, branch: string): Promise<void>\n  /**\n   * Show one commit (message + patch) — diff viewer (0.4.0). Fail-soft:\n   * undefined on any git failure; the payload is capped.\n   */\n  showCommit(cwd: string, hash: string): Promise<DiffResult | undefined>\n  /**\n   * Show the diff of one path — diff viewer (0.4.0). Without `baseCommit`:\n   * the working-tree view (staged + unstaged vs HEAD, e.g. uncommitted\n   * changes in a live worktree); with `baseCommit`: the range\n   * base..HEAD restricted to the path. Fail-soft: undefined on failure.\n   */\n  showPathDiff(cwd: string, path: string, baseCommit?: string): Promise<DiffResult | undefined>\n}\n\n/**\n * Build the task branch name `task/<标题>+<taskId>` (plan §9 拍板).\n *\n * Title sanitizing: whitespace runs collapse to `-`; git-illegal characters\n * (`~ ^ : ? * [ \\ / @ { }` and friends) are stripped; `..` collapses; the\n * segment is trimmed of leading/trailing `.-` and truncated to ~20 code\n * points; an empty result falls back to the bare `task/<taskId>`.\n *\n * Since issue #98 this delegates to the shared {@link buildBranchName} under\n * the factory-default preset, which reproduces the legacy output byte for\n * byte; the board may pick another preset instead.\n * @param title - the task title (already normalized 1..200 chars).\n * @param taskId - the task id (stable suffix).\n * @returns the branch name.\n */\nexport function sanitizeBranchName(title: string, taskId: string): string {\n  return buildBranchName(title, taskId, DEFAULT_BRANCH_NAME_MODE, DEFAULT_BRANCH_NAME_PREFIX)\n}\n\n/**\n * The canonical worktree path of a task inside its workspace (forward\n * slashes). R4②: the id is validated HERE so every present and future call\n * site is covered — a traversal-shaped id must never ride into a filesystem\n * path (the cleanup/purge flows `rm -rf` what this returns).\n */\nexport function worktreePathOf(workspacePath: string, taskId: string): string {\n  if (!isValidTaskId(taskId)) {\n    throw new Error(`Error: invalid_input: illegal task id ${JSON.stringify(taskId.slice(0, 40))}`)\n  }\n  const root = workspacePath.replace(/[\\\\/]+$/, '').replaceAll('\\\\', '/')\n  return `${root}/${WORKTREE_DIR}/${taskId}`\n}\n\n/** Real exec layer over child_process.execFile (windowsHide, timeout, maxBuffer). */\nconst realExec: ExecFn = (args, options) => new Promise(resolve => {\n  void (async () => {\n    const { execFile } = await import('node:child_process')\n    execFile('git', args, {\n      cwd: options.cwd,\n      timeout: options.timeout ?? QUICK_TIMEOUT_MS,\n      windowsHide: true,\n      maxBuffer: 4 * 1024 * 1024,\n      encoding: 'utf8',\n    }, (error, stdout, stderr) => {\n      resolve({ ok: error === null, stdout: String(stdout ?? ''), stderr: String(stderr ?? '') })\n    })\n  })().catch(() => resolve({ ok: false, stdout: '', stderr: 'exec unavailable' }))\n})\n\n/**\n * Build a {@link GitFace} over an injectable exec layer.\n * @param exec - the exec function (real `git` when omitted).\n */\nexport function createGitFace(exec: ExecFn = realExec): GitFace {\n  const quick = (args: string[], cwd?: string): Promise<ExecResult> => exec(args, { cwd, timeout: QUICK_TIMEOUT_MS })\n  const heavy = (args: string[], cwd?: string): Promise<ExecResult> => exec(args, { cwd, timeout: HEAVY_TIMEOUT_MS })\n\n  const dirtyLines = async (cwd: string): Promise<string[] | undefined> => {\n    try {\n      const status = await quick(['status', '--porcelain'], cwd)\n      if (!status.ok) return undefined\n      // A leftover with no .git can inherit the MAIN repo's clean status.\n      // Only the requested worktree's own status can authorize its removal.\n      const top = await quick(['rev-parse', '--show-toplevel'], cwd)\n      const normalize = (path: string) => process.platform === 'win32' ? resolve(path).toLowerCase() : resolve(path)\n      if (!top.ok || top.stdout.trim().length === 0 || normalize(top.stdout.trim()) !== normalize(cwd)) return undefined\n      return status.stdout.split('\\n').map(l => l.trim()).filter(l => l.length > 0)\n    } catch { return undefined }\n  }\n\n  // Per-root mutex (0.3.1): structural git ops on the SAME repository run one\n  // at a time — concurrent isolated executions must not race on git's locks.\n  const locks = new Map<string, Promise<unknown>>()\n  const withRootLock = <T>(root: string, fn: () => Promise<T>): Promise<T> => {\n    const prev = locks.get(root) ?? Promise.resolve()\n    const next = prev.then(fn, fn)\n    locks.set(root, next.catch(() => { /* the chain never blocks later ops */ }))\n    return next\n  }\n\n  return {\n    async detect(root) {\n      const r = await quick(['rev-parse', '--is-inside-work-tree'], root)\n      return r.ok && r.stdout.trim() === 'true'\n    },\n\n    async binaryAvailable() {\n      const r = await quick(['--version'])\n      return r.ok && r.stdout.startsWith('git version')\n    },\n\n    prepareWorktree: (root, path, branch, mode = 'fresh') => withRootLock(root, async () => {\n      // 续跑: a live worktree at the path is kept EXACTLY as-is — the agent's\n      // commits and uncommitted changes survive; the baseline becomes the\n      // worktree's own HEAD so evidence covers only the new run.\n      if (mode === 'reuse') {\n        const wtHead = await quick(['rev-parse', 'HEAD'], path)\n        // S14: a readable HEAD is not enough — the worktree must be on OUR\n        // branch, otherwise a user-created repo at the path would be silently\n        // taken over. Foreign or detached → fall through to fresh preparation.\n        const wtBranch = wtHead.ok ? await quick(['rev-parse', '--abbrev-ref', 'HEAD'], path) : undefined\n        if (wtHead.ok && wtHead.stdout.trim().length > 0\n          && wtBranch !== undefined && wtBranch.ok && wtBranch.stdout.trim() === branch) {\n          return { path, branch, baseCommit: wtHead.stdout.trim(), reused: true }\n        }\n        // No live worktree on our branch → fall through to a fresh preparation.\n      }\n\n      // Baseline: the main worktree's current HEAD (also validates the repo).\n      const head = await quick(['rev-parse', 'HEAD'], root)\n      if (!head.ok) return undefined\n      const baseCommit = head.stdout.trim()\n\n      const exists = await quick(['show-ref', '--verify', `refs/heads/${branch}`], root)\n      if (exists.ok) {\n        // Reuse the fixed branch name, but guarantee a FRESH baseline: drop\n        // any stale worktree at the path, move the branch to the current\n        // HEAD, then check the branch out again (每次全新，复用仅作选项保留).\n        await heavy(['worktree', 'remove', '--force', path], root)\n        await heavy(['worktree', 'prune'], root)\n        const moved = await heavy(['branch', '-f', branch, 'HEAD'], root)\n        if (!moved.ok) {\n          // The branch is pinned by ANOTHER live worktree — e.g. a previous\n          // cycle's in_review card still holding it — so it cannot be\n          // force-moved (`fatal: cannot force update the branch ... used by\n          // worktree at ...`). Degrade to a per-run branch instead of\n          // failing the whole preparation and running in the user's main\n          // checkout (#94); pinBranches records the fallback name and later\n          // runs reuse it normally (only our own path holds it then).\n          const fallback = `${branch}+r${crypto.randomUUID().slice(0, 8)}`\n          const added = await heavy(['worktree', 'add', '-b', fallback, path], root)\n          if (!added.ok) return undefined\n          return { path, branch: fallback, baseCommit }\n        }\n        const added = await heavy(['worktree', 'add', path, branch], root)\n        if (!added.ok) return undefined\n      } else {\n        const added = await heavy(['worktree', 'add', '-b', branch, path], root)\n        if (!added.ok) return undefined\n      }\n      return { path, branch, baseCommit }\n    }),\n\n    async collect(worktreePath, baseCommit, excludeRelPaths) {\n      const facts: SettlementFacts = { commits: [], commitsTotal: 0, dirtyFiles: [], dirtyFilesTotal: 0, changedFiles: 0 }\n      const range = `${baseCommit}..HEAD`\n\n      const head = await quick(['rev-parse', 'HEAD'], worktreePath)\n      if (head.ok) facts.headCommit = head.stdout.trim()\n\n      const log = await quick(['log', '--pretty=format:%h %s', range], worktreePath)\n      if (log.ok) {\n        const commits = log.stdout.split('\\n')\n          .map(line => line.trim())\n          .filter(line => line.length > 0)\n          .map(line => {\n            const space = line.indexOf(' ')\n            return space === -1\n              ? { hash: line, subject: '' }\n              : { hash: line.slice(0, space), subject: line.slice(space + 1) }\n          })\n        // Evidence caps (0.3.1): the ledger is rewritten whole on every\n        // mutation — cap what a huge branch/status dump can add to it.\n        facts.commitsTotal = commits.length\n        facts.commits = commits.slice(0, MAX_COMMIT_EVIDENCE)\n      }\n\n      const status = await quick(['status', '--porcelain'], worktreePath)\n      if (status.ok) {\n        // excludeRelPaths drops the mirror's nested repo worktrees — they\n        // read as untracked noise / gitlink drift here, not as this repo's\n        // uncommitted changes. Excluded on the RAW line (path extraction is\n        // shape-aware); the stored evidence keeps its trimmed 0.3.x shape.\n        const dirty = status.stdout.split('\\n')\n          .filter(l => l.trim().length > 0)\n          .filter(l => !statusLineUnder(l, excludeRelPaths ?? []))\n          .map(l => l.trim())\n        facts.dirtyFilesTotal = dirty.length\n        facts.dirtyFiles = dirty.slice(0, MAX_DIRTY_EVIDENCE)\n      }\n\n      const shortstat = await quick(['diff', '--shortstat', range], worktreePath)\n      if (shortstat.ok && shortstat.stdout.trim().length > 0) facts.diffStat = shortstat.stdout.trim()\n\n      const names = await quick(['diff', '--name-only', range], worktreePath)\n      if (names.ok) facts.changedFiles = names.stdout.split('\\n').filter(l => l.trim().length > 0).length\n\n      return facts\n    },\n\n    dirtyLines,\n\n    merge: (root, branch, exemptRelPaths) => withRootLock(root, async () => {\n      // Main-clean check. The plugin's own worktree directory\n      // (<root>/.dsh-worktrees) shows up as untracked noise and is EXEMPT —\n      // otherwise merging would be impossible without gitignoring it first.\n      const status = await quick(['status', '--porcelain'], root)\n      if (status.ok) {\n        const dirtyLines = status.stdout.split('\\n')\n          .filter(l => l.trim().length > 0)\n          .filter(l => !statusLineUnder(l, [WORKTREE_DIR, ...(exemptRelPaths ?? [])]))\n          .map(l => l.trim())\n        if (dirtyLines.length > 0) {\n          // Machine-readable tag: callers classify without parsing zh-CN text.\n          throw Object.assign(new Error(`主工作区有 ${dirtyLines.length} 处未提交修改，请先提交或暂存后再合并`), { code: 'dirty-tree' })\n        }\n      }\n      const merged = await heavy(['merge', '--no-ff', '--no-edit', branch], root)\n      if (!merged.ok) {\n        // Roll the half-finished merge back so the main worktree stays usable;\n        // report the ORIGINAL failure verbatim (不自动解决冲突).\n        await heavy(['merge', '--abort'], root)\n        throw new Error(`合并失败：${merged.stderr.trim().slice(0, 300)}`)\n      }\n    }),\n\n    async isAncestor(root, branch) {\n      // exit 0 = branch is an ancestor of (or equal to) HEAD → merge no-op.\n      const r = await quick(['merge-base', '--is-ancestor', branch, 'HEAD'], root)\n      return r.ok\n    },\n\n    removeWorktree: (root, worktreePath, opts) => withRootLock(root, async (): Promise<'removed' | 'unregistered'> => {\n      const status = await dirtyLines(worktreePath)\n      if (status === undefined) throw worktreeStatusError(worktreePath)\n      if (status.length > 0) {\n        // opts.exempt drops mirror-structural noise (nested child worktrees /\n        // gitlink drift) — the caller's aggregated check already refused real\n        // dirt before reaching here.\n        const lines = status\n          .filter(l => !statusLineUnder(l, opts?.exempt ?? []))\n          .map(l => l.trim())\n        if (lines.length > 0) {\n          // Machine-readable tag: purge flows classify without parsing zh-CN text.\n          throw Object.assign(new Error(`worktree 有 ${lines.length} 处未提交修改，拒绝删除：\\n${lines.slice(0, 10).join('\\n')}`), { code: 'dirty-worktree' })\n        }\n      }\n      const removed = await heavy(opts?.force === true\n        ? ['worktree', 'remove', '--force', worktreePath]\n        : ['worktree', 'remove', worktreePath], root)\n      if (removed.ok) return 'removed'\n      // S3: classify the failure WITHOUT parsing git's (localizable) stderr —\n      // a path absent from `worktree list` is an unregistered leftover, not\n      // an error the caller should relay verbatim.\n      const list = await quick(['worktree', 'list', '--porcelain'], root)\n      if (!list.ok) throw worktreeStatusError(worktreePath)\n      const registered = list.stdout.split('\\n')\n        .some(l => l.startsWith('worktree ')\n          && resolve(l.slice('worktree '.length).trim()).toLowerCase() === resolve(worktreePath).toLowerCase())\n      if (!registered) return 'unregistered'\n      throw new Error(`删除 worktree 失败：${(removed.stderr.trim() || removed.stdout.trim()).slice(0, 300)}`)\n    }),\n\n    deleteBranch: (root, branch) => withRootLock(root, async () => {\n      const deleted = await heavy(['branch', '-D', branch], root)\n      if (!deleted.ok) throw new Error(`删除分支失败：${deleted.stderr.trim().slice(0, 300)}`)\n    }),\n\n    async showCommit(cwd, hash) {\n      if (!isHash(hash)) return undefined\n      const r = await quick(['show', '--no-color', '--format=medium', hash], cwd)\n      if (!r.ok || r.stdout.trim().length === 0) return undefined\n      return capDiff(r.stdout)\n    },\n\n    async showPathDiff(cwd, path, baseCommit) {\n      const target = path.trim()\n      if (target.length === 0) return undefined\n      if (baseCommit !== undefined && isHash(baseCommit)) {\n        const r = await quick(['diff', '--no-color', `${baseCommit}..HEAD`, '--', target], cwd)\n        if (!r.ok) return undefined\n        if (r.stdout.trim().length === 0) return { text: '（该文件无差异）', truncated: false }\n        return capDiff(r.stdout)\n      }\n      // Working-tree view: staged + unstaged vs HEAD.\n      const r = await quick(['diff', '--no-color', 'HEAD', '--', target], cwd)\n      if (r.ok && r.stdout.trim().length > 0) return capDiff(r.stdout)\n      // Untracked files never appear in `git diff` — detect one and synthesize\n      // its new-file patch via --no-index (which exits 1 on differences, so\n      // its stdout is trusted whenever it carries a diff header).\n      const st = await quick(['status', '--porcelain', '--', target], cwd)\n      if (r.ok && st.ok && st.stdout.trim().startsWith('??')) {\n        const ni = await exec(['diff', '--no-color', '--no-index', '--', '/dev/null', target], { cwd, timeout: QUICK_TIMEOUT_MS })\n        if (ni.stdout.includes('diff --git')) return capDiff(ni.stdout)\n        return { text: `（未跟踪新文件：${target}）`, truncated: false }\n      }\n      if (!r.ok) return undefined\n      return { text: '（该文件无差异）', truncated: false }\n    },\n  }\n}\n"
    },
    {
      "path": "src/host/isolation.ts",
      "content": "/**\n * Worktree isolation orchestration (0.6.3): turns the single-repo worktree\n * flow into a whole-workspace MIRROR when a workspace holds parallel git\n * repositories — the workspace root repo plus its nested ones (plan §3/§4).\n *\n * Responsibilities (git.ts stays the narrow per-repo face):\n * - prepareMirror: discover the repos, prepare one worktree per repo under\n *   the task mirror directory (root repo at the mirror root, each nested\n *   repo at its relative path), with per-repo reuse (续跑) and a bounded\n *   partial-failure policy: the FIRST repo failing degrades the whole run\n *   to the original directory (legacy semantics), a later repo failing\n *   just drops it from the mirror (framing marks it 禁改 — the isolation\n *   boundary never blurs).\n * - removeMirror: children-first removal with an aggregated dirty\n *   pre-check (one dirty repo refuses the WHOLE mirror before anything is\n *   deleted). Children must go first: a nested worktree under the root\n *   worktree reads as untracked noise there, so the root worktree is only\n *   removable once they are gone.\n *\n * Preparation stays fail-soft at the execution boundary. Destructive removal\n * refuses unknown status and propagates errors to the user action.\n *\n * @module dsh-taskboard/host/isolation\n */\nimport { MAX_MIRROR_REPOS, isValidRelRepoPath } from '../shared/protocol.ts'\nimport { lstat, readdir, rmdir } from 'node:fs/promises'\nimport type { GitFace } from './git.ts'\nimport { statusLineUnder, worktreePathOf, worktreeStatusError } from './git.ts'\nimport type { RepoRef, RepoScanner } from './repos.ts'\n\n/** One prepared repo worktree inside a task mirror. */\nexport interface PreparedMirrorRepo {\n  /** Repo path relative to the workspace ('' = the workspace root repo). */\n  repo: string\n  /** The task branch checked out there. */\n  branch: string\n  /** Absolute worktree path (the working directory for this repo in the run). */\n  worktreePath: string\n  /** Baseline for evidence collection: main HEAD (fresh) or worktree HEAD (reuse). */\n  baseCommit: string\n  /** True when an existing live worktree was kept as-is (续跑). */\n  reused?: boolean\n}\n\n/** The mirror of one run: prepared repos + repos deliberately left out. */\nexport interface PreparedMirror {\n  /** Absolute path of the task mirror directory (the framing names it). */\n  root: string\n  /** Prepared worktrees in mirror order (root repo first when present). */\n  repos: PreparedMirrorRepo[]\n  /** Repos discovered but NOT mirrored (prepare failed); framing marks them 禁改. */\n  skipped: Array<{ repo: string; reason: string }>\n  /** True when EVERY prepared worktree was kept as-is (续跑 — framing picks the resume wording). */\n  allReused: boolean\n}\n\n/** Outcome of a mirror preparation: either a mirror or a degrade note. */\nexport type MirrorPrepareOutcome =\n  | { mirror: PreparedMirror }\n  | { note: string }\n\n/** Whether this mirror is exactly the legacy single-repo shape. */\nexport function isLegacySingle(mirror: PreparedMirror): boolean {\n  return mirror.repos.length === 1\n    && mirror.repos[0]!.repo === ''\n    && mirror.skipped.length === 0\n}\n\n/** Whether a repo key may ride into a mirror path (defense in depth under worktreePathOf). */\nfunction assertRepoKey(repo: string): void {\n  if (!isValidRelRepoPath(repo)) {\n    throw new Error('Error: invalid_input: illegal repo path ' + JSON.stringify(repo.slice(0, 80)))\n  }\n}\n\n/** Best-effort filesystem existence probe (fail-soft → false). */\nasync function pathExists(path: string): Promise<boolean> {\n  try {\n    const { stat } = await import('node:fs/promises')\n    return await stat(path).then(() => true, () => false)\n  } catch {\n    return false\n  }\n}\n\n/** Join a repo relative path under a base path (forward slashes). */\nfunction under(base: string, rel: string): string {\n  return rel === '' ? base : base + '/' + rel\n}\n\n/** Unlike preparation's fail-soft probe, deletion may only ignore ENOENT. */\nasync function removalPathExists(path: string): Promise<boolean> {\n  try {\n    const info = await lstat(path)\n    if (!info.isDirectory() || info.isSymbolicLink()) throw worktreeStatusError(path)\n    return true\n  } catch (error) {\n    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return false\n    throw worktreeStatusError(path, error)\n  }\n}\n\n/** A non-git mirror root is removable only when it contains checked children\n * and empty container directories. Files, .git markers, and symlinks refuse. */\nasync function assertPlainContainer(path: string, children: readonly string[], rel = ''): Promise<void> {\n  for (const entry of await readdir(path, { withFileTypes: true })) {\n    if (!entry.isDirectory() || entry.isSymbolicLink() || entry.name === '.git') throw worktreeStatusError(path)\n    const childRel = rel.length === 0 ? entry.name : rel + '/' + entry.name\n    if (!children.includes(childRel)) await assertPlainContainer(under(path, entry.name), children, childRel)\n  }\n}\n\n/** Git removes registered worktrees. Leftover containers may lose empty\n * directories only; never recursively unlink files after a status check. */\nasync function removeEmptyContainers(root: string): Promise<void> {\n  const directories: string[] = []\n  const inspect = async (path: string): Promise<void> => {\n    if (!await removalPathExists(path)) return\n    for (const entry of await readdir(path, { withFileTypes: true })) {\n      if (!entry.isDirectory() || entry.isSymbolicLink()) throw worktreeStatusError(path)\n      await inspect(under(path, entry.name))\n    }\n    directories.push(path)\n  }\n  try {\n    await inspect(root)\n    for (const path of directories) {\n      // rmdir also refuses files created since inspection (ENOTEMPTY).\n      try { await rmdir(path) }\n      catch (error) { if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error }\n    }\n  } catch (error) { throw worktreeStatusError(root, error) }\n}\n\n/**\n * Prepare the task mirror across every repo of the workspace.\n *\n * Repo list: the workspace root repo (GitFace.detect decides, whatever its\n * .git shape) leads, nested parallel repos follow in path order. Each repo\n * gets its own worktree on its pinned branch (or the shared default); reuse keeps live\n * worktrees as-is per repo (续跑), falling back to a fresh preparation per\n * repo — and a stale blocking directory gets one forced-fresh retry.\n */\nexport async function prepareMirror(\n  deps: { git: GitFace; scanner: RepoScanner },\n  args: { workspacePath: string; taskId: string; branch: string; branches?: Record<string, string>; reuse: boolean },\n): Promise<MirrorPrepareOutcome> {\n  const { git, scanner } = deps\n\n  // 1. Discover. The root repo is probed through the git face; nested repos\n  //    come from the bounded scanner.\n  const repos: RepoRef[] = []\n  let inside = false\n  try {\n    inside = await git.detect(args.workspacePath)\n  } catch { /* fail-soft → treated as \"root is not a repo\" */ }\n  if (inside) repos.push({ relPath: '', absPath: args.workspacePath })\n  let nested: RepoRef[] = []\n  try {\n    nested = await scanner.findNestedRepos(args.workspacePath)\n  } catch { nested = [] }\n  for (const repo of nested) {\n    assertRepoKey(repo.relPath)\n    repos.push(repo)\n  }\n\n  if (repos.length === 0) {\n    // Distinguish 未装 git from 非 git 仓库 (0.3.1 wording preserved).\n    let hasBinary = true\n    try {\n      hasBinary = await git.binaryAvailable()\n    } catch { /* fail-soft → repo-side wording */ }\n    return {\n      note: hasBinary\n        ? '当前项目不是 git 仓库，已在原目录执行'\n        : 'git 不可用（未安装或不在 PATH），已在原目录执行',\n    }\n  }\n  if (repos.length > MAX_MIRROR_REPOS) {\n    return { note: '工作区内 git 仓库数超过镜像上限（' + repos.length + ' > ' + MAX_MIRROR_REPOS + '），已在原目录执行' }\n  }\n\n  // 2. Prepare per repo. FIRST repo failing → whole-run degrade (legacy\n  //    semantics); a later failure drops just that repo from the mirror.\n  const mirrorRoot = worktreePathOf(args.workspacePath, args.taskId)\n  const prepared: PreparedMirrorRepo[] = []\n  const skipped: PreparedMirror['skipped'] = []\n  for (let i = 0; i < repos.length; i++) {\n    const repo = repos[i]!\n    const target = under(mirrorRoot, repo.relPath)\n    const branch = repo.relPath === '' ? args.branch : args.branches?.[repo.relPath] ?? args.branch\n    let info\n    try {\n      info = await git.prepareWorktree(repo.absPath, target, branch, args.reuse ? 'reuse' : 'fresh')\n    } catch { /* fail-soft */ }\n    if (info === undefined && args.reuse) {\n      // A stale non-matching directory can block reuse; force one fresh\n      // attempt (fresh mode already drops + prunes the stale worktree).\n      try {\n        info = await git.prepareWorktree(repo.absPath, target, branch, 'fresh')\n      } catch { /* fail-soft */ }\n    }\n    if (info === undefined) {\n      if (i === 0) return { note: 'worktree 准备失败（git 报错或目录被占用），已在原目录执行' }\n      skipped.push({ repo: repo.relPath, reason: 'worktree 准备失败' })\n      continue\n    }\n    prepared.push({\n      repo: repo.relPath,\n      branch: info.branch,\n      worktreePath: info.path,\n      baseCommit: info.baseCommit,\n      ...(info.reused === true ? { reused: true } : {}),\n    })\n  }\n  return {\n    mirror: {\n      root: mirrorRoot,\n      repos: prepared,\n      skipped,\n      allReused: prepared.length > 0 && prepared.every(p => p.reused === true),\n    },\n  }\n}\n\n/**\n * Remove a task whole mirror: aggregate the dirty pre-check across EVERY\n * repo worktree first (one dirty repo refuses everything, nothing is\n * deleted), then remove children before the root (see module doc).\n * Unknown status refuses deletion; a plain root container must contain only\n * verified children. After git removal, only empty directories are cleaned.\n * @throws with code dirty-mirror when any repo worktree holds uncommitted changes.\n */\nexport async function removeMirror(\n  deps: { git: GitFace; scanner: RepoScanner },\n  args: { workspacePath: string; taskId: string },\n): Promise<void> {\n  const { git, scanner } = deps\n  const mirrorRoot = worktreePathOf(args.workspacePath, args.taskId)\n  // Structural teardown must target a FRESH discovery: a stale TTL cache\n  // could miss a repo added since the last scan and strand its mirror\n  // worktree inside the root (which then reads as unremovable noise). The\n  // cache exists for the prepare/merge hot path, not for teardown.\n  scanner.clearCache()\n  let nested: RepoRef[] = []\n  try {\n    nested = await scanner.findNestedRepos(args.workspacePath)\n  } catch (error) { throw worktreeStatusError(mirrorRoot, error) }\n\n  const targets: Array<{ repo: string; repoRoot: string; path: string }> = []\n  for (const repo of nested) {\n    assertRepoKey(repo.relPath)\n    const path = under(mirrorRoot, repo.relPath)\n    if (await removalPathExists(path)) targets.push({ repo: repo.relPath, repoRoot: repo.absPath, path })\n  }\n  // The mirror ROOT is always a target (the legacy flow called removeWorktree\n  // unconditionally): when the workspace root is a repo this removes the root\n  // worktree; when it is not (plain mirror dir, already-gone path) git side\n  // status preflight proves it is a plain container or an already-gone path.\n  targets.push({ repo: '', repoRoot: args.workspacePath, path: mirrorRoot })\n\n  const childRels = targets.filter(t => t.repo !== '').map(t => t.repo)\n  const dirty: Array<{ repo: string; lines: string[] }> = []\n  const skipGit = new Set<string>()\n  for (const target of targets) {\n    const raw = await git.dirtyLines(target.path).catch(() => undefined)\n    if (raw === undefined) {\n      if (!await removalPathExists(target.path)) {\n        skipGit.add(target.path)\n        continue\n      }\n      if (target.repo !== '') throw worktreeStatusError(target.path)\n      // Plain container roots have no git status of their own. Prove that\n      // their only contents are the children checked by this same preflight.\n      try { await assertPlainContainer(target.path, childRels) }\n      catch (error) { throw worktreeStatusError(target.path, error) }\n      skipGit.add(target.path)\n      continue\n    }\n    // The root worktree's status lists its nested child worktrees as untracked\n    // noise (`?? sub/`) — those trees belong to the children (checked in their\n    // own pass below), not to the root repo's uncommitted changes. Without\n    // this exemption a fully committed mirror still reads as dirty and every\n    // cleanup route refuses forever (0.6.3 review fix).\n    const lines = target.repo === '' && raw !== undefined\n      ? raw.filter(l => !statusLineUnder(l, childRels))\n      : raw\n    if (lines !== undefined && lines.length > 0) dirty.push({ repo: target.repo, lines })\n  }\n  if (dirty.length > 0) {\n    const detail = dirty\n      .map(d => (d.repo === '' ? '根仓库' : d.repo) + '：\\n' + d.lines.slice(0, 10).join('\\n'))\n      .join('\\n')\n    throw Object.assign(\n      new Error('镜像中 ' + dirty.length + ' 个仓库有未提交修改，拒绝删除：\\n' + detail),\n      { code: 'dirty-mirror' },\n    )\n  }\n\n  // Removal walks the array FORWARD: children were pushed before the root, so\n  // this IS the children-first order. (The original reverse loop removed the\n  // root FIRST — its own doc said children-first; the P1 dirty refusal above\n  // masked the bug because the loop never actually ran on a real mirror.)\n  for (const target of targets) {\n    if (skipGit.has(target.path) && target.repo === '') continue\n    try {\n      // The root's structural noise (nested child worktrees / gitlink drift)\n      // survived the aggregated pre-check above — exempt + force is safe by\n      // construction: real dirt never got past it.\n      if (!skipGit.has(target.path)) {\n        await git.removeWorktree(target.repoRoot, target.path,\n          target.repo === '' ? { exempt: childRels, force: true } : undefined)\n      }\n      // Unregistered/partly removed children must not survive under a parent\n      // that is about to be force-removed with a structural-noise exemption.\n      if (target.repo !== '') await removeEmptyContainers(target.path)\n    } catch (error) {\n      // Never force-remove the parent after a child failed its own fresh\n      // status check or removal: the child's files are still inside it.\n      throw new Error('删除镜像失败：' + (target.repo === '' ? '根仓库' : target.repo) + '：' + (error instanceof Error ? error.message : String(error)), { cause: error })\n    }\n  }\n  await removeEmptyContainers(mirrorRoot)\n}\n\n/**\n * Absolute path of a repo main checkout inside the workspace (the fallback\n * cwd for diff views after a mirror is gone).\n */\nexport function repoMainPath(workspacePath: string, repo: string): string {\n  assertRepoKey(repo)\n  return under(workspacePath, repo)\n}\n"
    },
    {
      "path": "src/host/ledger-lock.ts",
      "content": "/** Cross-process ledger ownership, including recovery after a killed host. */\nimport { mkdir } from 'node:fs/promises'\nimport { mkdirSync, readdirSync, readFileSync, rmdirSync, statSync, unlinkSync, writeFileSync } from 'node:fs'\nimport { dirname, join } from 'node:path'\n\nconst STALE_LOCK_MS = 5 * 60_000\nconst LOCK_TIMEOUT_MS = STALE_LOCK_MS + 60_000\n\nexport interface LedgerLockOptions {\n  timeoutMs?: number\n  retryMs?: number\n}\n\n/** Only ESRCH establishes that a process is dead; EPERM is not evidence. */\nfunction ownerState(token: string): 'alive' | 'dead' | 'unknown' | 'legacy' {\n  const match = /^([1-9]\\d*):\\d+:[a-z0-9]+$/.exec(token)\n  const pid = match === null ? NaN : Number(match[1])\n  if (!Number.isSafeInteger(pid) || pid <= 0 || pid > 0x7fffffff) return 'legacy'\n  try { process.kill(pid, 0); return 'alive' } catch (error) {\n    return (error as NodeJS.ErrnoException).code === 'ESRCH' ? 'dead' : 'unknown'\n  }\n}\n\n/**\n * Recover unique owner entries, then remove ONLY an empty lock directory.\n * A second reclaimer cannot remove a replacement owner's different entry;\n * rmdir refuses a nonempty directory, closing the stat/unlink replacement race.\n * Legacy file locks are accepted during upgrade but never created here.\n */\nfunction recoverLock(lock: string): boolean {\n  try {\n    const before = statSync(lock)\n    if (before.isDirectory()) {\n      const entries = readdirSync(lock)\n      if (entries.length === 0 && Date.now() - before.mtimeMs <= STALE_LOCK_MS) return false\n      for (const entry of entries) {\n        const match = /^owner-([1-9]\\d*)-(\\d+)-([a-z0-9]+)$/.exec(entry)\n        if (match === null || ownerState(match.slice(1).join(':')) !== 'dead') return false\n        // Unique per acquisition: this path can never name a new owner's record.\n        try { unlinkSync(join(lock, entry)) } catch (error) {\n          if ((error as NodeJS.ErrnoException).code !== 'ENOENT') throw error\n        }\n      }\n      try { rmdirSync(lock); return true } catch (error) {\n        const code = (error as NodeJS.ErrnoException).code\n        if (code === 'ENOTEMPTY' || code === 'EEXIST') return false\n        if (code === 'ENOENT') return true\n        throw error\n      }\n    }\n    const token = readFileSync(lock, 'utf8')\n    const state = ownerState(token)\n    if (state === 'alive' || state === 'unknown') return false\n    if (state === 'legacy' && Date.now() - before.mtimeMs <= STALE_LOCK_MS) return false\n    const after = statSync(lock)\n    if (!after.isFile() || before.dev !== after.dev || before.ino !== after.ino\n      || before.mtimeMs !== after.mtimeMs || readFileSync(lock, 'utf8') !== token) return false\n    try { unlinkSync(lock); return true } catch (error) {\n      // A racing new writer may already have replaced the legacy file with a\n      // directory. unlink cannot remove that directory or its owner record.\n      if (statSync(lock).isDirectory()) return false\n      throw error\n    }\n  } catch (error) {\n    const code = (error as NodeJS.ErrnoException).code\n    if (code === 'ENOENT') return true\n    if (code === 'EISDIR' || code === 'ENOTDIR') return false\n    throw error\n  }\n}\n\nfunction release(lock: string, owner: string): void {\n  try { unlinkSync(owner) } catch { /* another recovery may have removed it */ }\n  try { rmdirSync(lock) } catch { /* never remove another owner's nonempty directory */ }\n}\n\n/** Exclusive sidecar directory around the complete ledger read/modify/write. */\nexport async function withLedgerWriteLock<T>(file: string, run: () => Promise<T>, options: LedgerLockOptions = {}): Promise<T> {\n  const lock = file + '.lock'\n  const token = process.pid + ':' + Date.now() + ':' + Math.random().toString(36).slice(2)\n  const owner = join(lock, 'owner-' + token.replaceAll(':', '-'))\n  const deadline = Date.now() + (options.timeoutMs ?? LOCK_TIMEOUT_MS)\n  await mkdir(dirname(file), { recursive: true })\n  for (;;) {\n    let acquired = false\n    try { mkdirSync(lock); acquired = true } catch (error) {\n      if ((error as NodeJS.ErrnoException).code !== 'EEXIST') throw error\n      if (recoverLock(lock)) continue\n    }\n    if (acquired) {\n      let ready = false\n      try {\n        writeFileSync(owner, token, { flag: 'wx' })\n        const entries = readdirSync(lock)\n        ready = entries.length === 1 && entries[0] === owner.slice(lock.length + 1)\n      } catch (error) {\n        if ((error as NodeJS.ErrnoException).code !== 'ENOENT') { release(lock, owner); throw error }\n      }\n      if (ready) {\n        // Callback EEXIST must propagate once, never restart the operation.\n        try { return await run() } finally { release(lock, owner) }\n      }\n      // An acquisition suspended while its empty directory was recovered must\n      // not enter a replacement owner's critical section.\n      release(lock, owner)\n    }\n    if (Date.now() >= deadline) throw new Error('timed out waiting for task ledger lock: ' + file)\n    await new Promise<void>(resolve => setTimeout(resolve, options.retryMs ?? 25))\n  }\n}\n"
    },
    {
      "path": "src/host/scheduler.ts",
      "content": "/**\n * Host-side cron scheduler: one tick per minute over the ledger's scheduled\n * tasks. Due tasks are first durably queued, then dispatched FIFO as global\n * capacity becomes available. A queued window remains eligible across a host\n * restart; only a window that was never queued can be classified as missed.\n *\n * @module dsh-taskboard/host/scheduler\n */\nimport { DEFAULT_DISPATCH_INTERVAL_MS, DEFAULT_MAX_CONCURRENT, isSpentOneShot, newCommentId, nextCronTime, normalizeBody, parseCron, type TaskLedger } from '../shared/protocol.ts'\nimport type { ExecutionService } from './execution.ts'\nimport type { TaskStore } from './store.ts'\n\n/** Tick cadence. */\nconst TICK_MS = 60_000\n\n/** Everything the scheduler needs. */\nexport interface SchedulerDeps {\n  store: TaskStore\n  execution: Pick<ExecutionService, 'run' | 'inFlight'>\n  now: () => number\n  /** Max concurrently running executions (default 3; must match the execution service). */\n  maxConcurrent?: number | (() => number)\n  /** Offline missed-window threshold in milliseconds. Queued work never uses it. */\n  skipAfterMs?: number | (() => number)\n  /** Optional shelf life for a durable queue entry in milliseconds; zero keeps it indefinitely. */\n  queueMaxAgeMs?: number | (() => number)\n  /** Minimum time between scheduler-created sessions; zero explicitly disables throttling. */\n  dispatchIntervalMs?: number | (() => number)\n  /** Timer face (injectable for tests). The timeout pair is optional so\n   *  older injections keep working; gaps fall back to the globals. */\n  timers?: {\n    setInterval(fn: () => void, ms: number): unknown\n    clearInterval(handle: unknown): void\n    setTimeout?(fn: () => void, ms: number): unknown\n    clearTimeout?(handle: unknown): void\n  }\n}\n\ntype SchedulerTimers = NonNullable<SchedulerDeps['timers']>\n\nconst DEFAULT_TIMERS: Required<SchedulerTimers> = {\n  setInterval: (fn: () => void, ms: number): unknown => setInterval(fn, ms),\n  clearInterval: (handle: unknown): void => { clearInterval(handle as Parameters<typeof clearInterval>[0]) },\n  setTimeout: (fn: () => void, ms: number): unknown => setTimeout(fn, ms),\n  clearTimeout: (handle: unknown): void => { clearTimeout(handle as Parameters<typeof clearTimeout>[0]) },\n}\n\n/**\n * The cron scheduler.\n */\nexport class SchedulerService {\n  private handle: unknown\n  private catchup: unknown\n  private timers: Required<SchedulerTimers> = DEFAULT_TIMERS\n  /** Reservations actively being handed to this scheduler instance's gate. */\n  private readonly dispatching = new Set<string>()\n  /** The one active pass: interval and catchup must never dispatch in parallel. */\n  private ticking: Promise<void> | undefined\n  /** Earliest time a new scheduled session may be opened. */\n  private nextDispatchAt = 0\n  private disposed = false\n  private dispatchWait: { handle: unknown; resolve: () => void } | undefined\n\n  /** @param deps - store + execution + clock. */\n  constructor(private readonly deps: SchedulerDeps) {}\n\n  private maxConcurrent(): number {\n    return typeof this.deps.maxConcurrent === 'function' ? this.deps.maxConcurrent() : this.deps.maxConcurrent ?? DEFAULT_MAX_CONCURRENT\n  }\n\n  private skipAfterMs(): number {\n    return typeof this.deps.skipAfterMs === 'function' ? this.deps.skipAfterMs() : this.deps.skipAfterMs ?? 5 * 60_000\n  }\n\n  private queueMaxAgeMs(): number {\n    return typeof this.deps.queueMaxAgeMs === 'function' ? this.deps.queueMaxAgeMs() : this.deps.queueMaxAgeMs ?? 0\n  }\n\n  private dispatchIntervalMs(): number {\n    return typeof this.deps.dispatchIntervalMs === 'function' ? this.deps.dispatchIntervalMs() : this.deps.dispatchIntervalMs ?? DEFAULT_DISPATCH_INTERVAL_MS\n  }\n\n  /** Start ticking. */\n  start(): void {\n    this.disposed = false\n    // Fill optional timer slots from the globals so a legacy injection that\n    // only carries the interval pair still works end to end.\n    this.timers = this.deps.timers === undefined ? DEFAULT_TIMERS : { ...DEFAULT_TIMERS, ...this.deps.timers }\n    // A tick rejection (disk error inside a mutation) must never surface as\n    // an unhandled rejection — log it and keep the schedule alive.\n    this.handle = this.timers.setInterval(() => { void this.tick().catch(error => {\n      console.error('[dsh-taskboard] scheduler tick failed:', error)\n    }) }, TICK_MS)\n    // Catch up promptly on host restart: run one tick soon after start. The\n    // handles are cleared on dispose so a torn-down scheduler never fires.\n    this.catchup = this.timers.setTimeout(() => { void this.tick().catch(error => {\n      console.error('[dsh-taskboard] scheduler tick failed:', error)\n    }) }, 3_000)\n  }\n\n  /** Stop ticking. */\n  dispose(): void {\n    this.disposed = true\n    if (this.dispatchWait !== undefined) {\n      this.timers.clearTimeout(this.dispatchWait.handle)\n      this.dispatchWait.resolve()\n      this.dispatchWait = undefined\n    }\n    if (this.catchup !== undefined) {\n      this.timers.clearTimeout(this.catchup)\n      this.catchup = undefined\n    }\n    if (this.handle === undefined) return\n    this.timers.clearInterval(this.handle)\n    this.handle = undefined\n  }\n\n  /** One scheduler pass (exported for tests). */\n  async tick(): Promise<void> {\n    if (this.ticking !== undefined) return this.ticking\n    let pass: Promise<void>\n    pass = this.tickOnce().finally(() => {\n      if (this.ticking === pass) this.ticking = undefined\n    })\n    this.ticking = pass\n    return pass\n  }\n\n  private async tickOnce(): Promise<void> {\n    // Load once before reading: snapshot() does not trigger a load, and the\n    // scheduler may be the first consumer after a host restart (otherwise it\n    // would tick over an empty ledger until something else loads it).\n    await this.deps.store.load()\n    const now = this.deps.now()\n    const ledger: TaskLedger = this.deps.store.snapshot()\n    for (const task of ledger.tasks) {\n      if (task.execution.mode !== 'scheduled' || task.trashedAt !== undefined) continue\n      // Only todo fires. A finished periodic run settles in review (its cron\n      // moves to a freshly minted successor todo card), and terminal/parked\n      // states retain their config so an explicit reopen can resume — none\n      // of these ever refire from here.\n      if (task.status !== 'todo') continue\n      // Already queued while this host was online: do not apply the offline\n      // missed-window policy to it. Dispatch happens in the FIFO pass below.\n      if (task.execution.queuedRunAt !== undefined) continue\n      if (task.execution.dispatchingRunAt !== undefined) {\n        // A prior host died after reserving but before opening the execution.\n        // Live reservations are protected by the in-memory guard; stale ones\n        // are returned to the durable queue on the first tick after restart.\n        const key = `${task.id}:${task.execution.dispatchingRunAt}`\n        if (!this.dispatching.has(key)) await this.restoreQueued(task.id, task.execution.dispatchingRunAt)\n        continue\n      }\n\n      if (task.execution.cron !== undefined) {\n        // Periodic (定期执行): refire at every cron match.\n        if (task.execution.nextRunAt === undefined) continue\n        if (task.execution.nextRunAt > now) continue\n        const missed = now - task.execution.nextRunAt > this.skipAfterMs()\n\n        if (missed) await this.advanceAndMark(task.id, now, undefined, task.execution.nextRunAt)\n        else await this.queueCron(task.id, now, task.execution.nextRunAt)\n      } else if (task.execution.runAt !== undefined) {\n        // One-shot (定时执行): fire once at the instant, then consume it.\n        const due = task.execution.runAt\n        if (due > now) continue\n        const missed = now - due > this.skipAfterMs()\n\n        if (missed) await this.consumeRunAt(task.id, now, due)\n        else await this.queueRunAt(task.id, now, due)\n      }\n    }\n\n    // Re-read after the queue mutations. Stable due-time order prevents cards\n    // later in the ledger from starving behind a fixed snapshot order.\n    const queued = this.deps.store.snapshot().tasks\n      .filter(task => task.execution.mode === 'scheduled' && task.status === 'todo'\n        && task.trashedAt === undefined && task.execution.queuedRunAt !== undefined)\n      .sort((a, b) => (a.execution.queuedRunAt! - b.execution.queuedRunAt!)\n        || ((a.execution.queuedAt ?? 0) - (b.execution.queuedAt ?? 0)) || a.id.localeCompare(b.id))\n    for (const task of queued) {\n      const queuedWindow = task.execution.queuedRunAt!\n      if (this.isExpired(task.execution.queuedAt, now)) {\n        await this.expireQueued(task.id, queuedWindow)\n        continue\n      }\n      if (this.deps.execution.inFlight() >= this.maxConcurrent()) break\n      await this.waitForDispatchSlot()\n      if (this.disposed || this.deps.execution.inFlight() >= this.maxConcurrent()) break\n      // Time may have advanced while waiting for a rate slot.\n      if (this.isExpired(task.execution.queuedAt, this.deps.now())) {\n        await this.expireQueued(task.id, queuedWindow)\n        continue\n      }\n      if (!await this.reserveDispatch(task.id, queuedWindow)) continue\n      this.nextDispatchAt = this.deps.now() + this.dispatchIntervalMs()\n      const key = `${task.id}:${queuedWindow}`\n      this.dispatching.add(key)\n      try {\n        const result = await this.deps.execution.run(task.id, 'scheduled', { scheduledWindow: queuedWindow }).catch(error => {\n          console.error('[dsh-taskboard] scheduled run failed:', error)\n          return undefined\n        })\n        // The production execution gate consumes this marker atomically with\n        // opening its running record. Retain this idempotent cleanup for narrow\n        // execution adapters (and test faces) that only report a successful\n        // dispatch and do not own the ledger mutation.\n        if (result?.ok) await this.markDispatched(task.id, queuedWindow)\n        else await this.restoreQueued(task.id, queuedWindow)\n        // A capacity race leaves the durable entry intact for the next pump.\n        if (result !== undefined && !result.ok && !result.error.includes('concurrency')) {\n          console.error('[dsh-taskboard] scheduled dispatch rejected:', result.error)\n        }\n      } finally {\n        this.dispatching.delete(key)\n      }\n    }\n  }\n\n  private isExpired(queuedAt: number | undefined, now: number): boolean {\n    const maxAge = this.queueMaxAgeMs()\n    return maxAge > 0 && queuedAt !== undefined && now - queuedAt >= maxAge\n  }\n\n  /** Yield until the scheduler-wide dispatch rate gate opens; never block Node's event loop. */\n  private async waitForDispatchSlot(): Promise<void> {\n    const wait = this.nextDispatchAt - this.deps.now()\n    if (wait <= 0 || this.disposed) return\n    await new Promise<void>(resolve => {\n      const handle = this.timers.setTimeout(() => {\n        if (this.dispatchWait?.handle === handle) this.dispatchWait = undefined\n        resolve()\n      }, wait)\n      this.dispatchWait = { handle, resolve }\n    })\n  }\n\n  /** Queue one periodic window and advance its next cron time atomically. */\n  private async queueCron(taskId: string, now: number, due: number): Promise<void> {\n    await this.deps.store.mutate('task-updated', ledger => {\n      const task = ledger.tasks.find(t => t.id === taskId)\n      if (task === undefined || task.execution.cron === undefined || task.execution.queuedRunAt !== undefined) return undefined\n      if (task.status !== 'todo' || task.trashedAt !== undefined || task.execution.nextRunAt !== due) return undefined\n      const match = parseCron(task.execution.cron)\n      const next = match === null ? undefined : nextCronTime(match, now) ?? undefined\n      if (next === undefined) return undefined\n      task.execution.nextRunAt = next\n      task.execution.que