      "path": "src/shared/protocol.ts",
      "content": "/**\n * Task domain model, state machine, urgency classes, and cron math — the\n * framework-free core shared verbatim by the host half (tools, store, routes,\n * scheduler) and, from P2 on, the browser half (board view).\n *\n * Everything here is a pure function over plain data: no imports beyond the\n * standard library, no I/O, no globals. Tests drive it directly.\n *\n * @module dsh-taskboard/shared/protocol\n */\n\nimport { normalizeExternalSource, normalizeExternalSyncRecords } from './external.ts'\nimport { applyHumanWaitingPatch } from './human-wait.ts'\n\n// ---------------------------------------------------------------------------\n// Status vocabulary\n// ---------------------------------------------------------------------------\n\n/**\n * Task lifecycle states. Main board columns render `backlog → todo →\n * in_progress → in_review → done`; `canceled` and `archived` are secondary\n * states collected under an \"other tasks\" tab. `blocked` is NOT a status —\n * it is a horizontal marker any non-terminal state may carry.\n */\nexport type TaskStatus =\n  | 'backlog'\n  | 'todo'\n  | 'in_progress'\n  | 'in_review'\n  | 'done'\n  | 'canceled'\n  | 'archived'\n\n/** Statuses shown as the five main board columns, in order. */\nexport const MAIN_STATUSES: readonly TaskStatus[] = [\n  'backlog',\n  'todo',\n  'in_progress',\n  'in_review',\n  'done',\n]\n\n/** Statuses collected under the secondary tab. */\nexport const SECONDARY_STATUSES: readonly TaskStatus[] = ['canceled', 'archived']\n\n/** Every valid status, main first. */\nexport const ALL_STATUSES: readonly TaskStatus[] = [...MAIN_STATUSES, ...SECONDARY_STATUSES]\n\n/**\n * Legal forward/sideways transitions. Anything not listed is rejected with\n * `invalid_transition`. `archived` is terminal.\n */\nconst TRANSITIONS: Readonly<Record<TaskStatus, readonly TaskStatus[]>> = {\n  backlog: ['todo', 'canceled'],\n  todo: ['in_progress', 'backlog', 'canceled'],\n  in_progress: ['in_review', 'todo', 'canceled'],\n  in_review: ['in_progress', 'todo', 'done', 'canceled'],\n  done: ['archived', 'todo'],\n  canceled: ['archived', 'todo'],\n  archived: [],\n}\n\n/**\n * Whether a status move is legal per the state machine.\n * @param from - current status.\n * @param to - requested status.\n * @returns true when the transition is allowed.\n */\nexport function canTransition(from: TaskStatus, to: TaskStatus): boolean {\n  return TRANSITIONS[from].includes(to)\n}\n\n/**\n * The claim move: the one transition that transfers ownership of a task to\n * the calling session. Guarded by the project (workspace) boundary in the\n * tool layer.\n */\nexport function isClaim(from: TaskStatus, to: TaskStatus): boolean {\n  return from === 'todo' && to === 'in_progress'\n}\n\n/** Statuses a `done` move may depart from (user confirmation only). */\nexport function canCompleteFrom(from: TaskStatus): boolean {\n  return from === 'in_review'\n}\n\n// ---------------------------------------------------------------------------\n// Urgency\n// ---------------------------------------------------------------------------\n\n/** Urgency classes with fixed UI colors. */\nexport type Urgency = 'urgent' | 'normal' | 'relaxed'\n\n/** All valid urgency values. */\nexport const URGENCIES: readonly Urgency[] = ['urgent', 'normal', 'relaxed']\n\n/** CSS color token per urgency: red / purple / blue. */\nexport const URGENCY_COLOR: Readonly<Record<Urgency, string>> = {\n  urgent: '#e5484d',\n  normal: '#8e4ec6',\n  relaxed: '#3e63dd',\n}\n\n// ---------------------------------------------------------------------------\n// Execution\n// ---------------------------------------------------------------------------\n\n/**\n * Per-task code isolation mode (0.3.0).\n * - `worktree`: each execution runs in a fresh `git worktree` on a dedicated\n *   task branch (`task/<标题>+<taskId>`) under `<workspace>/.dsh-worktrees/`.\n * - `none`: run in the workspace directory as before, zero git interaction.\n * Omitted = {@link DEFAULT_ISOLATION}; since 0.5.0 creation materializes the\n * board default onto the record (看板设置 → 执行隔离), and non-git projects\n * still auto-degrade at run time (the execution record carries an\n * `isolationNote` explaining why).\n */\nexport type IsolationMode = 'worktree' | 'none'\n\n/**\n * Factory-default isolation (0.5.0): 原目录执行. Applies when neither the\n * task record nor the board setting (`BoardSettings.defaultIsolation`)\n * says otherwise. Before 0.5.0 the implicit default was 'worktree'.\n */\nexport const DEFAULT_ISOLATION: IsolationMode = 'none'\n\n/** Factory default and safe UI/API range for concurrent task executions. */\nexport const DEFAULT_MAX_CONCURRENT = 3\nexport const MIN_MAX_CONCURRENT = 1\nexport const MAX_MAX_CONCURRENT = 100\n/** Factory default and safe UI/API range for offline missed-window handling. */\nexport const DEFAULT_SCHEDULE_MISSED_AFTER_MINUTES = 5\nexport const MIN_SCHEDULE_MISSED_AFTER_MINUTES = 1\nexport const MAX_SCHEDULE_MISSED_AFTER_MINUTES = 1_440\n/** A queued entry's optional shelf life. Zero deliberately preserves durable replay. */\nexport const DEFAULT_QUEUE_MAX_AGE_MINUTES = 0\nexport const MAX_QUEUE_MAX_AGE_MINUTES = 10_080\n/** Smallest user-selectable delay; zero explicitly disables dispatch throttling. */\nexport const MIN_DISPATCH_INTERVAL_MS = 0\n/** Default spacing between scheduler-created sessions. */\nexport const DEFAULT_DISPATCH_INTERVAL_MS = 1_000\nexport const MAX_DISPATCH_INTERVAL_MS = 60_000\n\n/** Factory default and safe UI/API range for completed tasks displayed on the board. */\nexport const DEFAULT_COMPLETED_DISPLAY_LIMIT = 50\nexport const MIN_COMPLETED_DISPLAY_LIMIT = 10\nexport const MAX_COMPLETED_DISPLAY_LIMIT = 500\n\n/** Validate an isolation value. */\nexport function asIsolation(raw: string): IsolationMode {\n  if (raw !== 'worktree' && raw !== 'none') {\n    throw new Error(\"isolation must be 'worktree' or 'none'\")\n  }\n  return raw\n}\n\n/** Resolve a task's effective isolation (omitted → the factory default). */\nexport function effectiveIsolation(task: Pick<TaskRecord, 'isolation'>): IsolationMode {\n  return task.isolation === undefined ? DEFAULT_ISOLATION : task.isolation\n}\n\n/**\n * Branch naming preset for worktree task branches (issue #98):\n * - `title-id`: `task/<标题>+<taskId>` — the factory default, byte-identical\n *   to the pre-#98 format.\n * - `id`: `task/<taskId>` (pure ASCII).\n * - `prefix-id`: `<prefix>/<taskId>`.\n * - `prefix-title-id`: `<prefix>/<标题>+<taskId>`.\n */\nexport type BranchNameMode = 'title-id' | 'id' | 'prefix-id' | 'prefix-title-id'\n\n/** Canonical list of supported branch naming presets. */\nexport const BRANCH_NAME_MODES: readonly BranchNameMode[] = ['title-id', 'id', 'prefix-id', 'prefix-title-id']\n\n/** Factory-default branch naming preset: the pre-#98 `task/<标题>+<taskId>`. */\nexport const DEFAULT_BRANCH_NAME_MODE: BranchNameMode = 'title-id'\n\n/** Factory-default branch prefix for the `prefix-*` presets. */\nexport const DEFAULT_BRANCH_NAME_PREFIX = 'task'\n\n/** Factory-default and hard cap (code points) for a generated branch segment. */\nconst BRANCH_SEGMENT_CAP = 20\n\n/**\n * Sanitize ONE branch name segment (issue #98): whitespace runs collapse to\n * `-`; git-illegal characters (`~ ^ : ? * [ \\ / @ { }` and friends) are\n * stripped; `..` collapses; the segment is trimmed of leading/trailing `.-`\n * and truncated to {@link BRANCH_SEGMENT_CAP} code points. Pure — shared by\n * the board preset builder and prefix validation.\n * @param segment - the raw segment (a task title or a board prefix).\n * @returns the sanitized segment; possibly empty (caller falls back).\n */\nexport function sanitizeBranchSegment(segment: string): string {\n  const s = segment.trim()\n    .replace(/\\s+/g, '-')\n    .replace(/[/\\\\~^:?*[\\]@{}\"'<>|#%&;$!`'=,;()]+/g, '')\n    .replace(/\\.\\.+/g, '.')\n    .replace(/^[-.\\s]+|[-.\\s]+$/g, '')\n  return Array.from(s).slice(0, BRANCH_SEGMENT_CAP).join('').replace(/^[-.]+|[-.]+$/g, '')\n}\n\n/**\n * Build a task branch name under a board naming preset (issue #98). The\n * `title-id` preset reproduces the legacy `task/<标题>+<taskId>` byte for\n * byte (empty sanitized title → bare `task/<taskId>`).\n * @param title - the task title (already normalized 1..200 chars).\n * @param taskId - the task id (stable suffix).\n * @param mode - the board naming preset.\n * @param prefix - the board prefix for `prefix-*` presets (pre-sanitized).\n * @returns the branch name.\n */\nexport function buildBranchName(title: string, taskId: string,\n  mode: BranchNameMode = DEFAULT_BRANCH_NAME_MODE, prefix: string = DEFAULT_BRANCH_NAME_PREFIX): string {\n  if (mode === 'id') return `task/${taskId}`\n  const head = sanitizeBranchSegment(title)\n  if (mode === 'prefix-id') return `${prefix}/${taskId}`\n  if (mode === 'prefix-title-id') return head.length === 0 ? `${prefix}/${taskId}` : `${prefix}/${head}+${taskId}`\n  return head.length === 0 ? `task/${taskId}` : `task/${head}+${taskId}`\n}\n\n/** Hard cap (code points) for a user-supplied full branch name. */\nconst BRANCH_NAME_CAP = 60\n\n/**\n * Sanitize a user-supplied FULL branch name (issue #98 task-level override).\n * Unlike {@link sanitizeBranchSegment} the `/` separator is KEPT so users may\n * express multi-level names (`feat/login`). Git-illegal characters are\n * stripped, whitespace collapses to `-`, `..` collapses, and every component\n * must be non-empty, must not start with `.-`, and must not end with\n * `.-` or `.lock`; the whole name is capped at {@link BRANCH_NAME_CAP} code\n * points.\n * @param raw - the raw user input.\n * @returns the sanitized name, or undefined when nothing legal remains\n *   (the caller falls back to the board naming preset).\n */\nexport function sanitizeCustomBranchName(raw: string): string | undefined {\n  const cleaned = raw.trim()\n    .replace(/\\s+/g, '-')\n    .replace(/[\\\\~^:?*[\\]@{}\"'<>|#%&;$!`'=,;()]+/g, '')\n    .replace(/\\/{2,}/g, '/')\n    .replace(/\\.\\.+/g, '.')\n  const parts = cleaned.split('/')\n    .map(p => p.replace(/^[.\\s-]+|[.\\s-]+$/g, '').replace(/\\.lock$/, ''))\n    .filter(p => p.length > 0)\n  if (parts.length === 0) return undefined\n  const capped = Array.from(parts.join('/')).slice(0, BRANCH_NAME_CAP).join('')\n    .replace(/^[-.]+/, '').replace(/[.\\s-]+$/, '')\n  return capped.length > 0 ? capped : undefined\n}\n\n/** Validate a board branch naming preset value. */\nexport function asBranchNameMode(raw: string): BranchNameMode {\n  if (!(BRANCH_NAME_MODES as readonly string[]).includes(raw)) {\n    throw new Error(`branchNameMode must be one of: ${BRANCH_NAME_MODES.join(', ')}`)\n  }\n  return raw as BranchNameMode\n}\n\n/** The effective branch naming preset (board setting → factory default). */\nexport function branchNameModeOf(settings?: BoardSettings): BranchNameMode {\n  return settings?.branchNameMode ?? DEFAULT_BRANCH_NAME_MODE\n}\n\n/** The effective branch prefix for `prefix-*` presets (board setting → factory default). */\nexport function branchNamePrefixOf(settings?: BoardSettings): string {\n  return settings?.branchNamePrefix ?? DEFAULT_BRANCH_NAME_PREFIX\n}\n\n/**\n * Execution permission preset (0.5.5). Matches DSH permission presets:\n * - 'workspace-write': 可写入工作区 (factory default)\n * - 'read-only': 仅可查看\n * - 'danger-full-access': 完全权限\n */\nexport type PermissionMode = 'workspace-write' | 'read-only' | 'danger-full-access'\n\n/** Factory default permission preset (0.5.5). */\nexport const DEFAULT_PERMISSION: PermissionMode = 'workspace-write'\n\n/** Canonical list of supported permission modes. */\nexport const ALL_PERMISSIONS: readonly PermissionMode[] = ['workspace-write', 'read-only', 'danger-full-access']\n\n/** Validate and normalize a permission string into a valid {@link PermissionMode}. */\nexport function asPermission(raw: unknown): PermissionMode {\n  if (typeof raw !== 'string') return DEFAULT_PERMISSION\n  const normalized = raw.trim()\n  if (normalized === 'workspace-write' || normalized === 'workspaceWrite') return 'workspace-write'\n  if (normalized === 'read-only' || normalized === 'readOnly') return 'read-only'\n  if (normalized === 'danger-full-access' || normalized === 'fullAccess') return 'danger-full-access'\n  throw new Error(\"permission must be 'workspace-write', 'read-only', or 'danger-full-access'\")\n}\n\n/**\n * Board-level settings persisted with the ledger (0.5.0). Only fields the\n * user explicitly set are present; absent fields follow factory defaults.\n */\nexport type BoardSettings = {\n  /** Default code isolation applied when a NEW task is created without an explicit choice. */\n  defaultIsolation?: IsolationMode\n  /** Branch naming preset for worktree task branches (issue #98; default 'title-id' = the pre-#98 format). */\n  branchNameMode?: BranchNameMode\n  /** Branch prefix for the `prefix-*` presets (issue #98; sanitized single segment, default 'task'). */\n  branchNamePrefix?: string\n  /** Automatically capture external workspace sessions into the taskboard (default: false). */\n  syncExternalSessions?: boolean\n  /**\n   * Allow an agent session to CLAIM a task of a project it reaches only through\n   * a linked (multi-root) workspace root instead of its own workspace root\n   * (default: false — the primary-root-only rule).\n   */\n  allowClaimFromLinkedRoots?: boolean\n  /** Default permission preset applied when a NEW task is created without an explicit choice (0.5.5, default: 'workspace-write'). */\n  defaultPermission?: PermissionMode\n  /** Model and optional reasoning effort materialized onto NEW tasks; absent = deployment default. */\n  defaultModel?: TaskModel\n  /** Agent preset materialized onto NEW tasks; absent = deployment default. */\n  defaultPresetId?: string\n  /** Workspace the NEW-task form starts from when the board has no project filter (0.9.3, #56); absent = first registered workspace. */\n  defaultWorkspaceId?: string\n  /** Global cap for simultaneously running taskboard executions. */\n  maxConcurrent?: number\n  /** Only never-queued windows older than this are classified as offline misses. */\n  scheduleMissedAfterMinutes?: number\n  /** Drop an already queued window after this many minutes; zero keeps it indefinitely. */\n  queueMaxAgeMinutes?: number\n  /** Minimum delay between scheduled session starts; zero explicitly disables throttling. */\n  dispatchIntervalMs?: number\n  /** Maximum number of completed (done) tasks displayed on the board (default: 50). */\n  completedDisplayLimit?: number\n}\n\n/** Validate raw input into sanitized {@link BoardSettings} (unknown fields dropped). */\nexport function asBoardSettings(raw: unknown): BoardSettings {\n  if (typeof raw !== 'object' || raw === null) {\n    throw new Error('board settings must be an object')\n  }\n  const e = raw as Record<string, unknown>\n  const out: BoardSettings = {}\n  if (e.defaultIsolation !== undefined) {\n    if (typeof e.defaultIsolation !== 'string') {\n      throw new Error(\"defaultIsolation must be 'worktree' or 'none'\")\n    }\n    out.defaultIsolation = asIsolation(e.defaultIsolation)\n  }\n  if (e.branchNameMode !== undefined) {\n    if (typeof e.branchNameMode !== 'string') {\n      throw new Error(`branchNameMode must be one of: ${BRANCH_NAME_MODES.join(', ')}`)\n    }\n    out.branchNameMode = asBranchNameMode(e.branchNameMode)\n  }\n  if (e.branchNamePrefix !== undefined) {\n    if (typeof e.branchNamePrefix !== 'string') throw new Error('branchNamePrefix must be a string')\n    // Fail-soft: an all-illegal prefix is dropped (the accessor falls back\n    // to 'task') instead of failing the whole settings write.\n    const prefix = sanitizeBranchSegment(e.branchNamePrefix)\n    if (prefix.length > 0) out.branchNamePrefix = prefix\n  }\n  if (e.syncExternalSessions !== undefined) {\n    if (typeof e.syncExternalSessions !== 'boolean') {\n      throw new Error('syncExternalSessions must be a boolean')\n    }\n    out.syncExternalSessions = e.syncExternalSessions\n  }\n  if (e.allowClaimFromLinkedRoots !== undefined) {\n    if (typeof e.allowClaimFromLinkedRoots !== 'boolean') {\n      throw new Error('allowClaimFromLinkedRoots must be a boolean')\n    }\n    out.allowClaimFromLinkedRoots = e.allowClaimFromLinkedRoots\n  }\n  if (e.defaultPermission !== undefined) {\n    out.defaultPermission = asPermission(e.defaultPermission)\n  }\n  if (e.defaultModel !== undefined) {\n    out.defaultModel = normalizeModel(e.defaultModel)\n  }\n  if (e.defaultPresetId !== undefined) {\n    if (typeof e.defaultPresetId !== 'string') throw new Error('defaultPresetId must be a string')\n    const id = e.defaultPresetId.trim()\n    if (id.length > 0) out.defaultPresetId = id\n  }\n  if (e.defaultWorkspaceId !== undefined) {\n    if (typeof e.defaultWorkspaceId !== 'string') throw new Error('defaultWorkspaceId must be a string')\n    const id = e.defaultWorkspaceId.trim()\n    if (id.length > 0) out.defaultWorkspaceId = id\n  }\n  if (e.maxConcurrent !== undefined) {\n    if (typeof e.maxConcurrent !== 'number' || !Number.isSafeInteger(e.maxConcurrent)\n      || e.maxConcurrent < MIN_MAX_CONCURRENT || e.maxConcurrent > MAX_MAX_CONCURRENT) {\n      throw new Error(`maxConcurrent must be an integer from ${MIN_MAX_CONCURRENT} to ${MAX_MAX_CONCURRENT}`)\n    }\n    out.maxConcurrent = e.maxConcurrent\n  }\n  if (e.scheduleMissedAfterMinutes !== undefined) {\n    if (typeof e.scheduleMissedAfterMinutes !== 'number' || !Number.isSafeInteger(e.scheduleMissedAfterMinutes)\n      || e.scheduleMissedAfterMinutes < MIN_SCHEDULE_MISSED_AFTER_MINUTES || e.scheduleMissedAfterMinutes > MAX_SCHEDULE_MISSED_AFTER_MINUTES) {\n      throw new Error(`scheduleMissedAfterMinutes must be an integer from ${MIN_SCHEDULE_MISSED_AFTER_MINUTES} to ${MAX_SCHEDULE_MISSED_AFTER_MINUTES}`)\n    }\n    out.scheduleMissedAfterMinutes = e.scheduleMissedAfterMinutes\n  }\n  if (e.queueMaxAgeMinutes !== undefined) {\n    if (typeof e.queueMaxAgeMinutes !== 'number' || !Number.isSafeInteger(e.queueMaxAgeMinutes)\n      || e.queueMaxAgeMinutes < DEFAULT_QUEUE_MAX_AGE_MINUTES || e.queueMaxAgeMinutes > MAX_QUEUE_MAX_AGE_MINUTES) {\n      throw new Error(`queueMaxAgeMinutes must be an integer from ${DEFAULT_QUEUE_MAX_AGE_MINUTES} to ${MAX_QUEUE_MAX_AGE_MINUTES}`)\n    }\n    out.queueMaxAgeMinutes = e.queueMaxAgeMinutes\n  }\n  if (e.dispatchIntervalMs !== undefined) {\n    if (typeof e.dispatchIntervalMs !== 'number' || !Number.isSafeInteger(e.dispatchIntervalMs)\n      || e.dispatchIntervalMs < MIN_DISPATCH_INTERVAL_MS || e.dispatchIntervalMs > MAX_DISPATCH_INTERVAL_MS) {\n      throw new Error(`dispatchIntervalMs must be an integer from ${MIN_DISPATCH_INTERVAL_MS} to ${MAX_DISPATCH_INTERVAL_MS}`)\n    }\n    out.dispatchIntervalMs = e.dispatchIntervalMs\n  }\n  if (e.completedDisplayLimit !== undefined) {\n    if (typeof e.completedDisplayLimit !== 'number' || !Number.isSafeInteger(e.completedDisplayLimit)\n      || e.completedDisplayLimit < MIN_COMPLETED_DISPLAY_LIMIT || e.completedDisplayLimit > MAX_COMPLETED_DISPLAY_LIMIT) {\n      throw new Error(`completedDisplayLimit must be an integer from ${MIN_COMPLETED_DISPLAY_LIMIT} to ${MAX_COMPLETED_DISPLAY_LIMIT}`)\n    }\n    out.completedDisplayLimit = e.completedDisplayLimit\n  }\n  return out\n}\n\n/** The effective default isolation for NEW tasks (board setting → factory default). */\nexport function defaultIsolationOf(settings?: BoardSettings): IsolationMode {\n  return settings?.defaultIsolation ?? DEFAULT_ISOLATION\n}\n\n/** The effective external session sync switch (board setting → factory default false). */\nexport function defaultSyncExternalSessionsOf(settings?: BoardSettings): boolean {\n  return settings?.syncExternalSessions ?? false\n}\n\n/** The effective linked-root claim switch (board setting → factory default false). */\nexport function allowClaimFromLinkedRootsOf(settings?: BoardSettings): boolean {\n  return settings?.allowClaimFromLinkedRoots ?? false\n}\n\n/** The effective default permission preset for NEW tasks (board setting → factory default 'workspace-write'). */\nexport function defaultPermissionOf(settings?: BoardSettings): PermissionMode {\n  return settings?.defaultPermission ?? DEFAULT_PERMISSION\n}\n\n/** Effective global execution cap (board setting → supplied deployment default). */\nexport function maxConcurrentOf(settings: BoardSettings | undefined, fallback = DEFAULT_MAX_CONCURRENT): number {\n  return settings?.maxConcurrent ?? fallback\n}\n\n/** Effective offline missed-window threshold in minutes (board setting → factory default). */\nexport function scheduleMissedAfterMinutesOf(settings?: BoardSettings): number {\n  return settings?.scheduleMissedAfterMinutes ?? DEFAULT_SCHEDULE_MISSED_AFTER_MINUTES\n}\n\n/** Effective queued-work shelf life in minutes; zero means durable replay. */\nexport function queueMaxAgeMinutesOf(settings?: BoardSettings): number {\n  return settings?.queueMaxAgeMinutes ?? DEFAULT_QUEUE_MAX_AGE_MINUTES\n}\n\n/** Effective minimum spacing between scheduled session starts. */\nexport function dispatchIntervalMsOf(settings?: BoardSettings): number {\n  return settings?.dispatchIntervalMs ?? DEFAULT_DISPATCH_INTERVAL_MS\n}\n\n/** Effective completed tasks display limit (board setting → factory default 50). */\nexport function completedDisplayLimitOf(settings?: BoardSettings): number {\n  return settings?.completedDisplayLimit ?? DEFAULT_COMPLETED_DISPLAY_LIMIT\n}\n\n/** How a task may run. */\nexport type ExecutionMode = 'claim' | 'scheduled'\n\n/** How a periodic cron task continues after a successful scheduled run. */\nexport type PeriodicCompletion = 'rearm' | 'spawn'\n/** Default periodic behavior: keep this round for review and create the next todo card. */\nexport const DEFAULT_PERIODIC_COMPLETION: PeriodicCompletion = 'spawn'\n\n/** How a scheduled task obtains its conversation when no existing session is selected. */\nexport type ScheduledSessionReuseMode = 'fresh' | 'reuse'\n\n/**\n * Per-task execution configuration. `claim` tasks wait for an in-project\n * session to claim them; `scheduled` tasks run on the host cron scheduler.\n */\nexport interface ExecutionConfig {\n  mode: ExecutionMode\n  /** Explicit existing project session to continue on scheduled runs. This is a mandatory selection. */\n  reuseSessionId?: string\n  /**\n   * Periodic-cron-only policy: `fresh` creates a conversation for every\n   * trigger; `reuse` creates one on the first trigger then continues it.\n   * Omitted is the legacy `reuse` behavior, retained for already-saved tasks.\n   */\n  sessionReuseMode?: ScheduledSessionReuseMode\n  /** Host-owned continuation pointer for `sessionReuseMode: 'reuse'`. */\n  autoReuseSessionId?: string\n  /** Effective configuration paired with {@link autoReuseSessionId}. */\n  autoReuseSessionKey?: string\n  /**\n   * Five-field cron expression (minute hour day month weekday). Present on\n   * PERIODIC scheduled tasks (定期执行): the scheduler refires the task each\n   * time it comes due while the card sits in todo.\n   */\n  cron?: string\n  /**\n   * Optional host-owned completion policy for periodic cron tasks. `rearm`\n   * returns this card to todo; `spawn` preserves it for review and creates a\n   * fresh todo successor. Omitted records use the {@link DEFAULT_PERIODIC_COMPLETION}.\n   */\n  periodicCompletion?: PeriodicCompletion\n  /**\n   * One-shot trigger time (epoch ms). Present on ONE-SHOT scheduled tasks\n   * (定时执行): the scheduler fires the task once when due and consumes the\n   * field. Mutually exclusive with {@link cron}.\n   */\n  runAt?: number\n  /** Next due time (epoch ms); maintained by the host scheduler. */\n  nextRunAt?: number\n  /**\n   * Original due window of a scheduled dispatch waiting for global capacity.\n   * Its presence is durable: a host restart must not reclassify an already\n   * online-and-queued run as a window missed while the host was down.\n   */\n  queuedRunAt?: number\n  /** When the scheduler put {@link queuedRunAt} into its durable FIFO queue. */\n  queuedAt?: number\n  /** A queue entry reserved for an execution gate but not yet running. */\n  dispatchingRunAt?: number\n  /** Last time the scheduler triggered this task (epoch ms). */\n  lastTriggeredAt?: number\n}\n\n/**\n * True when a scheduled task's trigger is fully spent: one-shot (定时一次)\n * with its {@link ExecutionConfig.runAt} consumed — fired and settled, missed\n * while the host was down, or dropped from the dispatch queue — or a cron\n * whose expression died (cron cleared, nothing queued/dispatching). A runAt\n * still present, even in the past, remains eligible for the scheduler's\n * next tick and must not be mistaken for a consumed trigger. The host\n * normalizes `mode` back to `'claim'` so it stays manually runnable and the\n * edit form never renders an unsaveable one-shot demanding a new future\n * time (issue #95).\n * @param exec - the execution config to inspect.\n */\nexport function isSpentOneShot(exec: ExecutionConfig): boolean {\n  return exec.mode === 'scheduled' && exec.cron === undefined\n    && exec.runAt === undefined\n    && exec.queuedRunAt === undefined\n    && exec.dispatchingRunAt === undefined\n}\n\n/**\n * Parse a five-field cron expression. Supported field syntax: star, star/step\n * (`* / n` without spaces), a single number, an `a-b` range, and comma lists\n * of those. Day-of-week accepts both 0 and 7 as Sunday (normalized to 0).\n *\n * @param expr - the expression to parse.\n * @returns the match sets per field, or null when invalid.\n */\nexport function parseCron(expr: string): CronMatch | null {\n  const fields = expr.trim().split(/\\s+/)\n  if (fields.length !== 5) return null\n  const ranges: ReadonlyArray<readonly [number, number]> = [\n    [0, 59],\n    [0, 23],\n    [1, 31],\n    [1, 12],\n    [0, 7],\n  ]\n  const sets: Array<Set<number>> = []\n  for (let i = 0; i < 5; i++) {\n    const [min, max] = ranges[i]!\n    const set = new Set<number>()\n    if (!parseCronField(fields[i]!, min, max, set)) return null\n    sets.push(set)\n  }\n  const weekdays = new Set<number>()\n  for (const day of sets[4]!) weekdays.add(day === 7 ? 0 : day)\n  return { minutes: sets[0]!, hours: sets[1]!, days: sets[2]!, months: sets[3]!, weekdays }\n}\n\n/** Parsed cron field match sets. */\nexport type CronMatch = {\n  minutes: ReadonlySet<number>\n  hours: ReadonlySet<number>\n  days: ReadonlySet<number>\n  months: ReadonlySet<number>\n  weekdays: ReadonlySet<number>\n}\n\n/** Parse one cron field into a match set; false on any syntax error. */\nfunction parseCronField(field: string, min: number, max: number, out: Set<number>): boolean {\n  for (const part of field.split(',')) {\n    const [range, stepRaw] = part.split('/')\n    const step = stepRaw === undefined ? 1 : Number.parseInt(stepRaw, 10)\n    if (!Number.isInteger(step) || step < 1) return false\n    let lo: number\n    let hi: number\n    if (range === undefined || range === '') return false\n    if (range === '*') {\n      lo = min\n      hi = max\n    } else if (range.includes('-')) {\n      const [a, b] = range.split('-')\n      lo = Number.parseInt(a ?? '', 10)\n      hi = Number.parseInt(b ?? '', 10)\n      if (!Number.isInteger(lo) || !Number.isInteger(hi)) return false\n    } else {\n      lo = Number.parseInt(range, 10)\n      if (!Number.isInteger(lo)) return false\n      hi = stepRaw === undefined ? lo : max\n    }\n    if (lo < min || hi > max || lo > hi) return false\n    for (let v = lo; v <= hi; v += step) out.add(v)\n  }\n  return out.size > 0\n}\n\n/**\n * The next time at or after `from` matching the cron sets (local time),\n * or null when no match exists within four years (e.g. Feb 30).\n * @param match - parsed cron sets.\n * @param from - epoch ms start point (inclusive match candidate).\n * @returns the next match's epoch ms, or null.\n */\nexport function nextCronTime(match: CronMatch, from: number): number | null {\n  // Walk minute by minute from the next whole minute, capped at ~4 years.\n  const start = new Date(from)\n  start.setSeconds(0, 0)\n  start.setMinutes(start.getMinutes() + 1)\n  const cap = from + 4 * 366 * 24 * 60 * 60 * 1000\n  let t = start.getTime()\n  while (t <= cap) {\n    const d = new Date(t)\n    if (\n      match.months.has(d.getMonth() + 1)\n      && match.days.has(d.getDate())\n      && match.weekdays.has(d.getDay())\n      && match.hours.has(d.getHours())\n      && match.minutes.has(d.getMinutes())\n    ) {\n      return t\n    }\n    t += 60_000\n  }\n  return null\n}\n\n// ---------------------------------------------------------------------------\n// Records\n// ---------------------------------------------------------------------------\n\n/** Who performed a write. */\nexport type Actor =\n  | { kind: 'user' }\n  | { kind: 'agent'; sessionId: string }\n  | { kind: 'system' }\n\n/** Structured row of a multi-repo merge system comment (0.6.4). */\nexport type SystemCommentRow = {\n  /** Repo path relative to the workspace ('' = the workspace root repo). */\n  repo: string\n  outcome: 'merged' | 'noop' | 'failed'\n  /** Failure reason (verbatim) when outcome = 'failed'. */\n  error?: string\n}\n\n/** A progress/report comment on a task. */\nexport type CommentRecord = {\n  id: string\n  /** Comment body (plain text; UI renders as pre-wrapped). */\n  body: string\n  /** Optimistic-concurrency version of this comment. */\n  version: number\n  createdAt: number\n  /**\n   * The session that wrote this comment; absent for user-written ones. Host\n   * system comments carry the acting session id, or a stable source tag\n   * ('sched' / 'host') when no session is involved.\n   */\n  threadId?: string\n  /**\n   * i18n key of a host-generated system message (0.6.4). The GUI localizes it\n   * at render time; `body` stays a zh fallback for agent tools / CSV / raw\n   * JSON views.\n   */\n  systemKey?: string\n  /** Flat {name} interpolation params for the system message. */\n  systemParams?: Record<string, string>\n  /** Structured per-repo rows for the multi-repo merge summary (0.6.4). */\n  systemRows?: SystemCommentRow[]\n  /**\n   * When this comment was delivered to the task's conversation as a user\n   * message (issue #51 Plan A explicit delivery); absent = still pending.\n   * Only user comments (no threadId, no systemKey) are ever delivered.\n   */\n  deliveredAt?: number\n  /** The execution that carried the delivery (live followup or the wake run). */\n  deliveredExecutionId?: string\n}\n\n/** One commit produced by an isolated execution (hash + subject). */\nexport type CommitInfo = { hash: string; subject: string }\n\n// ---------------------------------------------------------------------------\n// Multi-repo mirror isolation (0.6.3)\n// ---------------------------------------------------------------------------\n\n/**\n * Max repos ONE task mirror may cover (0.6.3): the workspace root repo plus\n * its parallel nested repos. A workspace discovering more degrades the whole\n * worktree run to the original directory (plan §4.1 — predictable, and never\n * a half-built mirror).\n */\nexport const MAX_MIRROR_REPOS = 8\n\n/**\n * Whether `rel` is a legal repo-path key (0.6.3): `''` = the workspace root\n * repo; otherwise a relative forward-slash path with no traversal/absolute\n * shape and no dot segments. These keys ride into filesystem joins\n * (`<workspace>/<rel>`) and ledger maps — the same R4 paranoia as task ids.\n */\nexport function isValidRelRepoPath(rel: string): boolean {\n  if (rel === '') return true\n  if (rel.length === 0 || rel.length > 300) return false\n  if (/^[A-Za-z]:[\\\\/]/.test(rel) || rel.startsWith('\\\\\\\\') || rel.startsWith('/')) return false\n  const parts = rel.split('/')\n  return parts.every(p =>\n    p.length > 0 && p !== '.' && p !== '..' && !p.startsWith('.') && !/[\\\\:*?\"<>|]/.test(p))\n}\n\n/**\n * Per-repo isolation + evidence facts for one execution (0.6.3 multi-repo\n * mirror). Present only when the mirror covers MORE than the workspace root\n * repo alone (or has skipped repos) — a plain single-repo run keeps the\n * legacy flat fields above, untouched, so old ledgers/clients stay blind to\n * this. The root repo (when mirrored) ALSO dual-writes the flat fields.\n */\nexport type ExecutionRepoEvidence = {\n  /** Repo path relative to the workspace ('' = the workspace root repo). */\n  repo: string\n  /** The task branch checked out in this repo's worktree. */\n  branch: string\n  /** Absolute path of the repo's worktree inside the task mirror. */\n  worktreePath: string\n  /** HEAD of the task branch before the execution started. */\n  baseCommit?: string\n  /** HEAD at settlement. */\n  headCommit?: string\n  /** Commits between baseCommit and headCommit (capped, newest first). */\n  commits?: CommitInfo[]\n  commitsTotal?: number\n  /** Uncommitted changes at settlement (`status --porcelain` lines, capped). */\n  dirtyFiles?: string[]\n  dirtyFilesTotal?: number\n  diffStat?: string\n  changedFiles?: number\n}\n\n/**\n * The structured execution report an agent submits at handoff (0.4.0).\n * Commits/dirty/diff facts are host-collected git evidence — the report\n * covers the BUSINESS side the host cannot see.\n */\nexport type ExecutionReport = {\n  /** What was done (1..2000 chars, required). */\n  summary: string\n  /** Files the agent changed (paths, ≤50 × 300 chars). */\n  changedFiles: string[]\n  /** How the work was self-verified (≤50 × 300 chars). */\n  checks: string[]\n  /** Produced artifacts worth reviewing (≤30 × 300 chars). */\n  artifacts: string[]\n  /** Known remaining risks / follow-ups (≤2000 chars, '' allowed). */\n  risk: string\n}\n\n/** One Definition-of-Done checklist item (0.4.0). */\nexport type ChecklistItem = {\n  id: string\n  /** What must be true for acceptance (1..200 chars). */\n  text: string\n  checked: boolean\n  /** Who checked it: an agent session id, or 'user' for GUI toggles. */\n  checkedBy?: string\n  /** When it was checked (epoch ms). */\n  checkedAt?: number\n  /** Evidence note attached when checking (≤400 chars). */\n  note?: string\n}\n\n/** One execution attempt of a task. */\nexport type ExecutionRecord = {\n  id: string\n  /** The session this execution ran in; set once the session is really started. */\n  sessionId?: string\n  /** Effective configuration of a scheduled session; used only for compatible reuse. */\n  sessionReuseKey?: string\n  /** Why a bound scheduled session was replaced with a fresh conversation. */\n  reuseFallbackNote?: string\n  /** Trigger: manual button, the host scheduler, or a user comment wake (issue #51). */\n  trigger: 'manual' | 'scheduled' | 'comment'\n  startedAt?: number\n  /** Most recent observed session activity, throttled by the host. */\n  lastActivityAt?: number\n  endedAt?: number\n  outcome: 'running' | 'succeeded' | 'failed' | 'cancelled'\n  error?: string\n  /** Code isolation actually used (`none` also covers degraded worktree runs). */\n  isolation?: IsolationMode\n  /** Why worktree isolation degraded to running in the original directory. */\n  isolationNote?: string\n  /** The task branch this execution worked on (worktree runs only). */\n  branch?: string\n  /** Absolute path of the dedicated worktree (worktree runs only). */\n  worktreePath?: string\n  /** HEAD of the task branch before the execution started. */\n  baseCommit?: string\n  /** HEAD at settlement. */\n  headCommit?: string\n  /** Commits between baseCommit and headCommit (hash + subject; capped at 50, newest first). */\n  commits?: CommitInfo[]\n  /** Total commits before the evidence cap (equals commits.length when under it). */\n  commitsTotal?: number\n  /** Uncommitted changes present at settlement (`git status --porcelain` lines; capped at 100). */\n  dirtyFiles?: string[]\n  /** Total uncommitted lines before the evidence cap. */\n  dirtyFilesTotal?: number\n  /** Aggregate diff stat between baseCommit and headCommit. */\n  diffStat?: string\n  /** How many files differ between baseCommit and headCommit. */\n  changedFiles?: number\n  /** Per-repo facts of a multi-repo mirror run (0.6.3; absent on single-repo runs). */\n  repos?: ExecutionRepoEvidence[]\n  /** The agent's structured report, submitted via taskboard_execution_report. */\n  report?: ExecutionReport\n}\n\n/** The per-model override a task may carry; absent = session default model. */\nexport type TaskModel = {\n  provider: string\n  model: string\n  /** Thinking intensity / reasoning effort (optional; e.g. 'low', 'medium', 'high', 'none'). */\n  reasoningEffort?: string\n}\n\n/** One task on the board. */\nexport type TaskRecord = {\n  /** External tracker provenance; local execution state remains independent. */\n  external?: import('./external.ts').ExternalSource\n  id: string\n  title: string\n  description: string\n  /** Extra execution prompt; the execution session receives title+description+prompt. */\n  prompt: string\n  /** Owning project: a DSH workspace id. */\n  workspaceId: string\n  urgency: Urgency\n  status: TaskStatus\n  /** Horizontal marker: work cannot continue right now (any non-terminal status). */\n  blocked: boolean\n  /** Omitted = infer; true = explicit human wait; false = suppress inference. */\n  waitingForHuman?: boolean\n  /** Explanation only; never put credentials or secret values here. */\n  waitingReason?: string\n  execution: ExecutionConfig\n  model?: TaskModel\n  /** Code isolation for executions (omitted = the worktree default; see {@link IsolationMode}). */\n  isolation?: IsolationMode\n  /**\n   * The agent preset execution sessions are composed from (omitted = the\n   * deployment default preset). Recorded on the session header and mounted\n   * via the presets service at creation — this is what hands the session its\n   * tool set. Editable any time (each run composes fresh).\n   */\n  presetId?: string\n  /**\n   * Execution permission preset (0.5.5; see {@link PermissionMode}).\n   */\n  permission?: PermissionMode\n  /**\n   * Definition-of-Done acceptance checklist (0.4.0). Agents may append items\n   * and check/uncheck them (with evidence); the GUI may edit the whole list.\n   * Unchecked items highlight at review time; done stays user-only.\n   */\n  checklist?: ChecklistItem[]\n  /**\n   * The task branch fixed at the FIRST worktree creation. When the user (or\n   * an agent tool, issue #98) supplied an explicit branch it is used as-is\n   * (sanitized); otherwise it is generated from the board naming preset\n   * (`buildBranchName`, default the legacy `task/<标题>+<taskId>`).\n   * Renaming the task afterwards never changes it (history preservation).\n   * If preparation must use a fallback because another worktree holds this\n   * branch, the actual fallback replaces the pin for merge and continuation.\n   * Multi-repo mirror runs (0.6.3): this stays the WORKSPACE ROOT repo's\n   * branch; every nested repo pins its own under {@link branches}.\n   */\n  branch?: string\n  /**\n   * Per-repo task branches of a multi-repo mirror task (0.6.3): repo path\n   * relative to the workspace (never `''` — the root uses {@link branch})\n   * → branch name. Pinned at the repo's FIRST successful worktree creation,\n   * same rename-proof and collision-fallback semantics as {@link branch}.\n   */\n  branches?: Record<string, string>\n  /**\n   * The session currently holding the in-progress claim (explicit claim or a\n   * live execution). Present only while `status === 'in_progress'`: any move\n   * out of in_progress releases it. `updatedBy` is audit-only — user edits no\n   * longer erase the holder.\n   */\n  claimedBy?: string\n  /** When the current holder claimed the task (epoch ms). */\n  claimedAt?: number\n  version: number\n  createdAt: number\n  updatedAt: number\n  createdBy: Actor\n  updatedBy: Actor\n  comments: CommentRecord[]\n  executions: ExecutionRecord[]\n  /** How many older execution records were pruned by the retention cap. */\n  executionsPruned?: number\n  /**\n   * Id of the task this card continues (0.7.x periodic execution): when a\n   * PERIODIC scheduled task succeeds, the finished card moves to in_review\n   * and a fresh todo card carrying the cron is minted to keep the cycle\n   * going. Absent on originally created tasks.\n   */\n  spawnedFrom?: string\n  /** Soft-delete marker set by agent `taskboard_delete`; user confirms the purge. */\n  trashedAt?: number\n}\n\n/** Retention cap: how many execution records each task keeps (oldest pruned). */\nexport const MAX_EXECUTIONS = 20\n\n/**\n * Enforce the execution-record retention cap on one task (in place): keep the\n * newest {@link MAX_EXECUTIONS} records, count the dropped ones in\n * `executionsPruned`. Running records are always the newest, never dropped.\n * @param task - the task to prune.\n */\nexport function pruneExecutions(task: TaskRecord): void {\n  if (task.executions.length <= MAX_EXECUTIONS) return\n  const dropped = task.executions.length - MAX_EXECUTIONS\n  task.executions = task.executions.slice(-MAX_EXECUTIONS)\n  task.executionsPruned = (task.executionsPruned ?? 0) + dropped\n}\n\n/**\n * Mint the successor card of a PERIODIC scheduled task that just succeeded\n * (0.7.x): the finished card goes to in_review for acceptance while this\n * fresh todo card carries the cron onward, keeping the cycle alive. The\n * next run is recomputed from `now` (no compensating catch-up burst).\n * Task branches are NOT carried over (#94): each cycle pins its own\n * `task/<标题>+<taskId>` on its first run, because the predecessor's live\n * in_review worktree holds its branch checked out until acceptance.\n * Pure: the caller pushes the returned record into the ledger.\n * @param source - the finished periodic task (still carrying its cron).\n * @param prevExecutionId - id of the execution that just succeeded.\n * @param now - current epoch ms.\n * @returns the successor task record.\n */\nexport function spawnNextCycle(source: TaskRecord, prevExecutionId: string | undefined, now: number): TaskRecord {\n  const cron = source.execution.cron\n  if (cron === undefined) throw new Error('spawnNextCycle: source task has no cron')\n  const match = parseCron(cron)\n  const next = match === null ? undefined : nextCronTime(match, now) ?? undefined\n  if (next === undefined) throw new Error('spawnNextCycle: cron has no upcoming match within 4 years')\n  return {\n    id: newTaskId(),\n    title: source.title,\n    description: source.description,\n    prompt: source.prompt,\n    workspaceId: source.workspaceId,\n    urgency: source.urgency,\n    status: 'todo',\n    blocked: false,\n    execution: { mode: 'scheduled', cron, nextRunAt: next, periodicCompletion: source.execution.periodicCompletion ?? DEFAULT_PERIODIC_COMPLETION,\n      ...(source.execution.reuseSessionId !== undefined ? { reuseSessionId: source.execution.reuseSessionId } : {}),\n      ...(source.execution.sessionReuseMode !== undefined ? { sessionReuseMode: source.execution.sessionReuseMode } : {}),\n      ...(source.execution.autoReuseSessionId !== undefined ? { autoReuseSessionId: source.execution.autoReuseSessionId } : {}),\n      ...(source.execution.autoReuseSessionKey !== undefined ? { autoReuseSessionKey: source.execution.autoReuseSessionKey } : {}) },\n    ...(source.model !== undefined ? { model: structuredClone(source.model) } : {}),\n    ...(source.isolation !== undefined ? { isolation: source.isolation } : {}),\n    ...(source.presetId !== undefined ? { presetId: source.presetId } : {}),\n    ...(source.permission !== undefined ? { permission: source.permission } : {}),\n    ...(source.checklist !== undefined\n      ? { checklist: source.checklist.map(item => ({ ...item, checked: false, checkedBy: undefined, checkedAt: undefined, note: undefined })) }\n      : {}),\n    // Issue #94: branch/branches are deliberately NOT inherited. The\n    // predecessor's in_review card keeps its live worktree (holding the\n    // branch checked out) until a human accepts it; a successor pinned to\n    // the same branch could never `git branch -f` it and would silently\n    // degrade to in-place execution from cycle 2 on. The successor derives\n    // its own `task/<标题>+<新taskId>` on its first run instead.\n    spawnedFrom: source.id,\n    version: 1,\n    createdAt: now,\n    updatedAt: now,\n    createdBy: { kind: 'system' },\n    updatedBy: { kind: 'system' },\n    comments: [{\n      id: newCommentId(),\n      body: normalizeBody(`[系统] 定期任务上一轮执行完毕（执行 ${prevExecutionId ?? '未知'}），本卡承接定时继续下一轮；上一轮成果见 ${source.id} 的待验收。`),\n      systemKey: 'sys.spawnedFrom',\n      systemParams: { sourceId: source.id, executionId: prevExecutionId ?? '' },\n      version: 1,\n      createdAt: now,\n    }],\n    executions: [],\n  }\n}\n\n/** The whole durable ledger. */\nexport type TaskLedger = {\n  /** Non-secret sync metadata commits atomically with imported tasks. */\n  externalSync?: Record<string, import('./external.ts').ExternalSyncRecord>\n  schemaVersion: number\n  /** Global monotonic revision; every mutation bumps it. */\n  revision: number\n  tasks: TaskRecord[]\n  /** Board-level settings (0.5.0); absent on ledgers never touched by 设置. */\n  settings?: BoardSettings\n}\n\n/** Current ledger format version. */\nexport const LEDGER_SCHEMA_VERSION = 1\n\n/** An empty ledger. */\nexport function emptyLedger(): TaskLedger {\n  return { schemaVersion: LEDGER_SCHEMA_VERSION, revision: 0, tasks: [] }\n}\n\n// ---------------------------------------------------------------------------\n// ids\n// ---------------------------------------------------------------------------\n\n/** Random base36 suffix. */\nfunction suffix(): string {\n  return Math.random().toString(36).slice(2, 8)\n}\n\n/**\n * Legal task id charset (R4): `t-<base36>-<base36>` from {@link newTaskId},\n * and the ONLY shape accepted from the outside (import) or used to build\n * filesystem paths (worktree dirs). Ids ride into `join(ws, '.dsh-worktrees',\n * id)` — a lax charset here is an arbitrary-directory delete primitive.\n */\nexport function isValidTaskId(id: string): boolean {\n  return /^[A-Za-z0-9][A-Za-z0-9_-]{0,99}$/.test(id)\n}\n\n/** Mint a task id. */\nexport function newTaskId(): string {\n  return `t-${Date.now().toString(36)}-${suffix()}`\n}\n\n/** Mint a comment id. */\nexport function newCommentId(): string {\n  return `c-${Date.now().toString(36)}-${suffix()}`\n}\n\n/** Mint a checklist item id. */\nexport function newChecklistItemId(): string {\n  return `k-${Date.now().toString(36)}-${suffix()}`\n}\n\n/** Mint an execution id. */\nexport function newExecutionId(): string {\n  return `e-${Date.now().toString(36)}-${suffix()}`\n}\n\n// ---------------------------------------------------------------------------\n// validation helpers (input shaping for tools and routes)\n// ---------------------------------------------------------------------------\n\n/**\n * Validate and normalize a title: trimmed, 1..200 chars.\n * @param raw - the raw input.\n * @returns the normalized title.\n * @throws when empty or too long.\n */\nexport function normalizeTitle(raw: string): string {\n  const t = raw.trim()\n  if (t.length === 0 || t.length > 200) {\n    throw new Error('title must be 1..200 characters')\n  }\n  return t\n}\n\n/**\n * Validate a task prompt: trimmed, at most 8000 chars; empty becomes ''.\n * @param raw - the raw input.\n */\nexport function normalizePrompt(raw: string | undefined): string {\n  const t = (raw ?? '').trim()\n  if (t.length > 8000) throw new Error('prompt must be at most 8000 characters')\n  return t\n}\n\n/**\n * Validate and normalize a comment body: trimmed, 1..4000 chars.\n * @param raw - the raw input.\n */\nexport function normalizeBody(raw: string): string {\n  const t = raw.trim()\n  if (t.length === 0 || t.length > 4000) {\n    throw new Error('comment body must be 1..4000 characters')\n  }\n  return t\n}\n\n/**\n * Validate an urgency value.\n * @param raw - the raw input.\n */\nexport function asUrgency(raw: string): Urgency {\n  if (!URGENCIES.includes(raw as Urgency)) {\n    throw new Error(`urgency must be one of: ${URGENCIES.join(', ')}`)\n  }\n  return raw as Urgency\n}\n\n/**\n * Validate a status value.\n * @param raw - the raw input.\n */\nexport function asStatus(raw: string): TaskStatus {\n  if (!ALL_STATUSES.includes(raw as TaskStatus)) {\n    throw new Error(`status must be one of: ${ALL_STATUSES.join(', ')}`)\n  }\n  return raw as TaskStatus\n}\n\n/**\n * Parse a raw runAt input: epoch ms number or ISO date string → epoch ms.\n * @param raw - untyped runAt value.\n * @returns the epoch ms, or undefined when absent.\n */\nfunction normalizeRunAt(raw: unknown): number | undefined {\n  if (raw === undefined || raw === null) return undefined\n  if (typeof raw === 'number' && Number.isFinite(raw)) return Math.trunc(raw)\n  if (typeof raw === 'string') {\n    const t = Date.parse(raw)\n    if (Number.isNaN(t)) throw new Error('execution.runAt is not a valid time (epoch ms or ISO string)')\n    return t\n  }\n  throw new Error('execution.runAt must be an epoch ms number or an ISO date string')\n}\n\n/**\n * Validate an execution config request from raw tool/route input.\n * `scheduled` requires either a valid cron (periodic, 定期执行) or a runAt\n * instant (one-shot, 定时执行); the two are mutually exclusive. A cron's\n * first `nextRunAt` is computed from `now`.\n * @param raw - raw execution input ({@link ExecutionConfig} fields, untyped).\n * @param now - current epoch ms.\n * @param opts - `allowPastRunAt` lets the import path keep a historical\n *   one-shot instant instead of rejecting it.\n * @returns the normalized config.\n */\nexport function normalizeExecution(\n  raw: { mode?: string; cron?: string; runAt?: unknown; periodicCompletion?: unknown; reuseSessionId?: unknown; sessionReuseMode?: unknown },\n  now: number,\n  opts?: { allowPastRunAt?: boolean },\n): ExecutionConfig {\n  const mode = raw.mode ?? 'claim'\n  if (mode !== 'claim' && mode !== 'scheduled') {\n    throw new Error(\"execution.mode must be 'claim' or 'scheduled'\")\n  }\n  if (mode === 'claim') {\n    if (raw.periodicCompletion !== undefined) throw new Error('execution.periodicCompletion requires a cron schedule')\n    if (raw.reuseSessionId !== undefined) throw new Error('execution.reuseSessionId requires a scheduled task')\n    if (raw.sessionReuseMode !== undefined) throw new Error('execution.sessionReuseMode requires a scheduled task')\n    return { mode }\n  }\n  if (raw.reuseSessionId !== undefined && (typeof raw.reuseSessionId !== 'string' || raw.reuseSessionId.length === 0\n    || raw.reuseSessionId.length > 256 || raw.reuseSessionId.trim() !== raw.reuseSessionId || /[\\x00-\\x1f\\x7f]/.test(raw.reuseSessionId))) {\n    throw new Error('execution.reuseSessionId must be a valid session id')\n  }\n  const reuseSession = raw.reuseSessionId === undefined ? {} : { reuseSessionId: raw.reuseSessionId as string }\n  if (raw.sessionReuseMode !== undefined && raw.sessionReuseMode !== 'fresh' && raw.sessionReuseMode !== 'reuse') {\n    throw new Error(\"execution.sessionReuseMode must be 'fresh' or 'reuse'\")\n  }\n  const sessionReuseMode = raw.sessionReuseMode === undefined ? {} : { sessionReuseMode: raw.sessionReuseMode as ScheduledSessionReuseMode }\n  const runAt = normalizeRunAt(raw.runAt)\n  const cron = (raw.cron ?? '').trim()\n  if (cron.length > 0 && runAt !== undefined) {\n    throw new Error('execution: cron and runAt are mutually exclusive (periodic vs one-shot)')\n  }\n  if (runAt !== undefined) {\n    if (raw.periodicCompletion !== undefined) throw new Error('execution.periodicCompletion requires a cron schedule')\n    if (raw.sessionReuseMode !== undefined) throw new Error('execution.sessionReuseMode requires a cron schedule')\n    if (!opts?.allowPastRunAt && runAt <= now) throw new Error('execution.runAt must be in the future')\n    return { mode, runAt, nextRunAt: runAt, ...reuseSession }\n  }\n  const match = parseCron(cron)\n  if (match === null) throw new Error('execution.cron is not a valid 5-field cron expression')\n  const next = nextCronTime(match, now)\n  if (next === null) throw new Error('execution.cron never matches within 4 years')\n  const periodicCompletion = raw.periodicCompletion ?? DEFAULT_PERIODIC_COMPLETION\n  if (periodicCompletion !== 'rearm' && periodicCompletion !== 'spawn') {\n    throw new Error(\"execution.periodicCompletion must be 'rearm' or 'spawn'\")\n  }\n  return { mode, cron, nextRunAt: next, periodicCompletion, ...reuseSession, ...sessionReuseMode }\n}\n\n/**\n * The effective prompt of a task: title+description, with the explicit\n * prompt appended when set — title+description+prompt.\n * @param task - the task.\n */\nexport function effectivePrompt(task: TaskRecord): string {\n  const head = task.title\n  const body = task.description.length > 0 ? `${head}\\n\\n${task.description}` : head\n  return task.prompt.length > 0 ? `${body}\\n\\n${task.prompt}` : body\n}\n\n/**\n * Whether the task is currently claimed by a session (running state).\n * @param task - the task.\n */\nexport function isClaimedBy(task: TaskRecord): string | undefined {\n  return task.status === 'in_progress' && task.claimedBy !== undefined ? task.claimedBy : undefined\n}\n\n/**\n * Maintain the explicit claim fields around a status change: entering\n * in_progress under a session records the holder (an execution-start or an\n * agent claim); every move out of in_progress releases the claim (handoff,\n * give-back, cancel). A user-driven move into in_progress records no holder —\n * no session works on it yet.\n * @param task - the task being written (mutated in place).\n * @param to - the target status.\n * @param now - current epoch ms.\n * @param holder - the session id claiming the task, when applicable.\n */\nexport function syncClaim(task: TaskRecord, to: TaskStatus, now: number, holder?: string): void {\n  if (to !== 'in_progress') {\n    delete task.claimedBy\n    delete task.claimedAt\n  } else if (holder !== undefined) {\n    task.claimedBy = holder\n    task.claimedAt = now\n  }\n}\n\n/**\n * Collect unique execution session IDs associated with a task:\n * - executions with a non-empty `sessionId`\n * Creator and claim sessions may serve other tasks and are never included.\n * Bulk ARCHIVE semantics: only sessions this task owns are listed, so the\n * user's originating conversation is never swept up. For UI navigation and\n * follow-up routing use {@link taskSessionId} instead.\n * @param task - the task record to inspect.\n * @returns an array of distinct session IDs in stable discovery order.\n */\nexport function taskAssociatedSessionIds(task: TaskRecord): string[] {\n  const seen = new Set<string>()\n  const result: string[] = []\n  const push = (raw: unknown) => {\n    if (typeof raw === 'string') {\n      const trimmed = raw.trim()\n      if (trimmed.length > 0 && !seen.has(trimmed)) {\n        seen.add(trimmed)\n        result.push(trimmed)\n      }\n    }\n  }\n\n  if (Array.isArray(task.executions)) {\n    for (const ex of task.executions) {\n      if (ex !== null && typeof ex === 'object') {\n        push((ex as { sessionId?: unknown }).sessionId)\n      }\n    }\n  }\n  return result\n}\n\n/**\n * The ONE conversation a card points at for navigation and follow-up, by\n * descending priority:\n *\n * 1. the running execution's session;\n * 2. the most recent execution that recorded a session;\n * 3. the session holding the claim (only meaningful while in progress);\n * 4. a scheduled binding (`autoReuseSessionId` / `reuseSessionId`);\n * 5. the AGENT session that created the card — the conversation the work was\n *    asked for in — then the last agent editor as a final fallback.\n *\n * Rules 1–4 cover work the board itself executed. Rule 5 exists because a card\n * created in a conversation and worked on in that same conversation records NO\n * execution (nothing spawned a session), so without it five of six cards could\n * not be navigated back to the conversation they came from.\n *\n * Deliberately NOT {@link taskAssociatedSessionIds}: that one answers \"which\n * sessions does this task OWN\" for archiving and must stay execution-only,\n * while this one answers \"where does the human talk to this task\".\n * @param task - the task record to inspect.\n * @returns the session id, or undefined when the card has no conversation yet.\n */\nexport function taskSessionId(task: TaskRecord): string | undefined {\n  const running = task.executions?.find(ex => ex.outcome === 'running')\n  if (running?.sessionId !== undefined && running.sessionId.length > 0) return running.sessionId\n  const sessionExecution = task.executions === undefined\n    ? undefined\n    : [...task.executions].reverse().find(ex => ex.sessionId !== undefined && ex.sessionId.length > 0)\n  if (sessionExecution?.sessionId !== undefined) return sessionExecution.sessionId\n  if (task.claimedBy !== undefined && task.claimedBy.startsWith('session-')) return task.claimedBy\n  if (task.execution?.autoReuseSessionId !== undefined) return task.execution.autoReuseSessionId\n  if (task.execution?.reuseSessionId !== undefined) return task.execution.reuseSessionId\n  if (task.createdBy?.kind === 'agent' && task.createdBy.sessionId !== undefined) return task.createdBy.sessionId\n  if (task.updatedBy?.kind === 'agent' && task.updatedBy.sessionId !== undefined) return task.updatedBy.sessionId\n  return undefined\n}\n\n/**\n * Validate and normalize a pinned model: `{ provider, model, reasoningEffort? }`,\n * provider and model must be non-empty trimmed strings.\n * @param raw - the raw input.\n * @returns the normalized model.\n * @throws when the shape or the fields are invalid.\n */\nexport function normalizeModel(raw: unknown): TaskModel {\n  if (typeof raw !== 'object' || raw === null) {\n    throw new Error('model must be { provider: string, model: string }')\n  }\n  const { provider, model, reasoningEffort } = raw as { provider?: unknown; model?: unknown; reasoningEffort?: unknown }\n  if (typeof provider !== 'string' || typeof model !== 'string') {\n    throw new Error('model must be { provider: string, model: string }')\n  }\n  const p = provider.trim()\n  const m = model.trim()\n  if (p.length === 0 || m.length === 0) {\n    throw new Error('model.provider and model.model must be non-empty strings')\n  }\n  const eff = typeof reasoningEffort === 'string' && reasoningEffort.trim().length > 0 ? reasoningEffort.trim() : undefined\n  return { provider: p, model: m, ...(eff !== undefined ? { reasoningEffort: eff } : {}) }\n}\n\n// ---------------------------------------------------------------------------\n// template category validation (0.8.8)\n// ---------------------------------------------------------------------------\n\n/** Length cap for a user-defined template category label. */\nexport const MAX_TEMPLATE_CATEGORY_LENGTH = 30\n\n/**\n * Normalize a template category label: trimmed; empty means the default\n * bucket (undefined, not a stored empty string).\n * @param raw - the raw category value.\n * @throws when the value is not a string or exceeds the length cap.\n */\nexport function normalizeTemplateCategory(raw: unknown): string | undefined {\n  if (raw === undefined) return undefined\n  if (typeof raw !== 'string') throw new Error('template category must be a string')\n  const category = raw.trim()\n  if (category.length === 0) return undefined\n  if (category.length > MAX_TEMPLATE_CATEGORY_LENGTH) {\n    throw new Error(`template category must be 1..${MAX_TEMPLATE_CATEGORY_LENGTH} characters`)\n  }\n  return category\n}\n\n// ---------------------------------------------------------------------------\n// checklist + report validation (0.4.0)\n// ---------------------------------------------------------------------------\n\n/** Checklist size cap per task. */\nexport const MAX_CHECKLIST_ITEMS = 30\n\n/** Checklist item text cap (chars). */\nexport const MAX_CHECKLIST_TEXT = 200\n\n/**\n * Validate and normalize one checklist text line: trimmed, 1..200 chars.\n * @param raw - the raw text.\n * @throws when empty or too long.\n */\nexport function normalizeChecklistText(raw: string): string {\n  const t = raw.trim()\n  if (t.length === 0 || t.length > MAX_CHECKLIST_TEXT) {\n    throw new Error(`checklist item text must be 1..${MAX_CHECKLIST_TEXT} characters`)\n  }\n  return t\n}\n\n/**\n * Build a fresh unchecked checklist from plain text lines (create route /\n * templates / tool adds).\n * @param texts - the item texts (validated individually).\n */\nexport function checklistFromTexts(texts: readonly string[]): ChecklistItem[] {\n  const items = texts.map(text => ({ id: newChecklistItemId(), text: normalizeChecklistText(text), checked: false }))\n  if (items.length > MAX_CHECKLIST_ITEMS) {\n    throw new Error(`checklist may hold at most ${MAX_CHECKLIST_ITEMS} items`)\n  }\n  return items\n}\n\n/**\n * Validate and normalize a full checklist array (GUI update route, import):\n * missing ids are minted, text is checked, checked flags must be booleans,\n * checkedBy/checkedAt are kept only on checked items.\n * @param raw - untyped array from the wire.\n * @throws with a readable reason on any invalid entry.\n */\nexport function normalizeChecklist(raw: unknown): ChecklistItem[] {\n  if (!Array.isArray(raw)) throw new Error('checklist must be an array')\n  if (raw.length > MAX_CHECKLIST_ITEMS) {\n    throw new Error(`checklist may hold at most ${MAX_CHECKLIST_ITEMS} items`)\n  }\n  return raw.map((entry): ChecklistItem => {\n    if (typeof entry !== 'object' || entry === null) throw new Error('checklist item must be an object')\n    const e = entry as Record<string, unknown>\n    const text = normalizeChecklistText(typeof e.text === 'string' ? e.text : '')\n    const id = typeof e.id === 'string' && e.id.trim().length > 0 ? e.id.trim() : newChecklistItemId()\n    const checked = e.checked === true\n    const checkedBy = typeof e.checkedBy === 'string' ? e.checkedBy.trim().slice(0, 100) : undefined\n    const checkedAt = typeof e.checkedAt === 'number' && Number.isFinite(e.checkedAt) ? e.checkedAt : undefined\n    const note = typeof e.note === 'string' && e.note.trim().length > 0 ? e.note.trim().slice(0, 400) : undefined\n    if (!checked) return { id, text, checked: false }\n    return {\n      id,\n      text,\n      checked: true,\n      ...(checkedBy !== undefined && checkedBy.length > 0 ? { checkedBy } : {}),\n      ...(checkedAt !== undefined ? { checkedAt } : {}),\n      ...(note !== undefined ? { note } : {}),\n    }\n  })\n}\n\n/** Checklist progress: how many items are checked (absent checklist → 0/0). */\nexport function checklistProgress(task: Pick<TaskRecord, 'checklist'>): { done: number; total: number } {\n  const items = task.checklist ?? []\n  return { done: items.filter(i => i.checked).length, total: items.length }\n}\n\n/** Report string-list caps. */\nconst REPORT_LIST_CAPS = { changedFiles: 50, checks: 50, artifacts: 30 } as const\n\n/** Per-entry cap for report lists (chars). */\nconst REPORT_ENTRY_MAX = 300\n\n/** Validate one report string list: strings trimmed 1..300 chars. */\nfunction normalizeReportList(raw: unknown, field: keyof typeof REPORT_LIST_CAPS): string[] {\n  if (raw === undefined) return []\n  if (!Array.isArray(raw)) throw new Error(`report.${field} must be an array of strings`)\n  const out = raw.map(entry => {\n    if (typeof entry !== 'string') throw new Error(`report.${field} must be an array of strings`)\n    const t = entry.trim()\n    if (t.length === 0 || t.length > REPORT_ENTRY_MAX) {\n      throw new Error(`report.${field} entries must be 1..${REPORT_ENTRY_MAX} characters`)\n    }\n    return t\n  })\n  if (out.length > REPORT_LIST_CAPS[field]) {\n    throw new Error(`report.${field} may hold at most ${REPORT_LIST_CAPS[field]} entries`)\n  }\n  return out\n}\n\n/**\n * Validate and normalize a structured execution report.\n * @param raw - untyped tool/route input.\n * @throws with a readable reason on any invalid field.\n */\nexport function normalizeExecutionReport(raw: unknown): ExecutionReport {\n  if (typeof raw !== 'object' || raw === null) throw new Error('report must be an object')\n  const e = raw as Record<string, unknown>\n  const summary = typeof e.summary === 'string' ? e.summary.trim() : ''\n  if (summary.length === 0 || summary.length > 2000) {\n    throw new Error('report.summary must be 1..2000 characters')\n  }\n  const risk = typeof e.risk === 'string' ? e.risk.trim().slice(0, 2000) : ''\n  return {\n    summary,\n    changedFiles: normalizeReportList(e.changedFiles, 'changedFiles'),\n    checks: normalizeReportList(e.checks, 'checks'),\n    artifacts: normalizeReportList(e.artifacts, 'artifacts'),\n    risk,\n  }\n}\n\n// ---------------------------------------------------------------------------\n// ledger import validation (0.4.0)\n// ---------------------------------------------------------------------------\n\n/** Result classifying every task in an import file against the live ledger. */\nexport type ImportPlan = {\n  externalSync?: Record<string, import('./external.ts').ExternalSyncRecord>\n  /** Structurally valid tasks whose ids are new (merge adds them). */\n  create: TaskRecord[]\n  /** Structurally valid tasks whose ids already exist (merge replaces them). */\n  overwrite: TaskRecord[]\n  /** Invalid entries with a human-readable reason (never imported). */\n  invalid: Array<{ id?: string; reason: string }>\n  /** The file's board settings (0.5.0); replace-mode swaps them, merge keeps the live ones. */\n  settings?: BoardSettings\n}\n\n/** One unknown-value read helper: string fields with defaults. */\nfunction strOr(raw: Record<string, unknown>, key: string, fallback: string): string {\n  const v = raw[key]\n  return typeof v === 'string' ? v : fallback\n}\n\n/** One unknown-value read helper: finite numbers with defaults. */\nfunction numOr(raw: Record<string, unknown>, key: string, fallback: number): number {\n  const v = raw[key]\n  return typeof v === 'number' && Number.isFinite(v) ? v : fallback\n}\n\n/** Evidence caps for imported per-repo facts (aligns the host's collect caps). */\nconst IMPORT_COMMIT_CAP = 50\nconst IMPORT_DIRTY_CAP = 100\n\n/**\n * Sanitize an imported per-task branches map (0.6.3): legal repo keys only,\n * non-empty branch strings, capped at {@link MAX_MIRROR_REPOS} entries.\n * @returns undefined when nothing legal remains.\n */\nexport function normalizeBranchesMap(raw: unknown): Record<string, string> | undefined {\n  if (typeof raw !== 'object' || raw === null) return undefined\n  const out: Record<string, string> = {}\n  for (const [key, value] of Object.entries(raw as Record<string, unknown>)) {\n    if (Object.keys(out).length >= MAX_MIRROR_REPOS) break\n    if (typeof value !== 'string' || value.trim().length === 0 || value.length > 200) continue\n    if (key === '' || !isValidRelRepoPath(key)) continue\n    out[key] = value.trim()\n  }\n  return Object.keys(out).length > 0 ? out : undefined\n}\n\n/**\n * Sanitize ONE imported per-repo evidence entry (0.6.3): rebuilds the record\n * field by field, capping evidence arrays like the host's own collection.\n * @returns undefined for a structurally illegal entry (dropped, not fatal).\n */\nexport function normalizeRepoEvidence(raw: unknown): ExecutionRepoEvidence | undefined {\n  if (typeof raw !== 'object' || raw === null) return undefined\n  const e = raw as Record<string, unknown>\n  if (typeof e.repo !== 'string' || !isValidRelRepoPath(e.repo)) return undefined\n  if (typeof e.branch !== 'string' || e.branch.length === 0 || e.branch.length > 200) return undefined\n  if (typeof e.worktreePath !== 'string' || e.worktreePath.length === 0 || e.worktreePath.length > 1000) return undefined\n  const commits = Array.isArray(e.commits)\n    ? e.commits.filter((c): c is CommitInfo =>\n        typeof c === 'object' && c !== null && typeof (c as CommitInfo).hash === 'string'\n          && typeof (c as CommitInfo).subject === 'string').slice(0, IMPORT_COMMIT_CAP)\n    : undefined\n  const dirtyFiles = Array.isArray(e.dirtyFiles)\n    ? e.dirtyFiles.filter((l): l is string => typeof l === 'string').slice(0, IMPORT_DIRTY_CAP)\n    : undefined\n  return {\n    repo: e.repo,\n    branch: e.branch,\n    worktreePath: e.worktreePath,\n    ...(typeof e.baseCommit === 'string' ? { baseCommit: e.baseCommit.slice(0, 100) } : {}),\n    ...(typeof e.headCommit === 'string' ? { headCommit: e.headCommit.slice(0, 100) } : {}),\n    ...(commits !== undefined && commits.length > 0 ? { commits } : {}),\n    ...(typeof e.commitsTotal === 'number' && Number.isFinite(e.commitsTotal) ? { commitsTotal: e.commitsTotal } : {}),\n    ...(dirtyFiles !== undefined && dirtyFiles.length > 0 ? { dirtyFiles } : {}),\n    ...(typeof e.dirtyFilesTotal === 'number' && Number.isFinite(e.dirtyFilesTotal) ? { dirtyFilesTotal: e.dirtyFilesTotal } : {}),\n    ...(typeof e.diffStat === 'string' ? { diffStat: e.diffStat.slice(0, 500) } : {}),\n    ...(typeof e.changedFiles === 'number' && Number.isFinite(e.changedFiles) ? { changedFiles: e.changedFiles } : {}),\n  }\n}\n\n/**\n * Validate ONE imported task record (pure): rebuilds it field by field with\n * the normal validators, minting missing ids and re-arming cron. Executions\n * left `running` by the exporting machine are marked failed — their\n * settlement watchers died there and can never settle here.\n * @param raw - the untyped record.\n * @param now - current epoch ms (defaults for timestamps).\n * @returns the rebuilt record, or a rejection reason.\n */\nexport function validateImportedTask(raw: unknown, now: number): { ok: true; task: TaskRecord } | { ok: false; reason: string } {\n  if (typeof raw !== 'object' || raw === null) return { ok: false, reason: 'not an object' }\n  const e = raw as Record<string, unknown>\n  const id = typeof e.id === 'string' ? e.id.trim() : ''\n  const fail = (reason: string): { ok: false; reason: string } => ({ ok: false, reason })\n  // R4①: length alone let traversal-shaped ids (`../../x`, `..\\..\\x`) into\n  // the ledger; the charset gate is the primary defense for every downstream\n  // filesystem use of a task id.\n  if (!isValidTaskId(id)) return fail('missing/invalid id (must match ^[A-Za-z0-9][A-Za-z0-9_-]{0,99}$)')\n  try {\n    const rawExecution = typeof e.execution === 'object' && e.execution !== null\n      ? e.execution as { mode?: string; cron?: string; runAt?: unknown; periodicCompletion?: unknown; reuseSessionId?: unknown; sessionReuseMode?: unknown; autoReuseSessionId?: unknown; autoReuseSessionKey?: unknown; queuedRunAt?: unknown; queuedAt?: unknown; dispatchingRunAt?: unknown }\n      : {}\n    const execution = normalizeExecution(\n      rawExecution,\n      now,\n      { allowPastRunAt: true },\n    )\n    // These pointers are host-owned runtime state. Retain only well-formed\n    // values from an exported ledger; a stale pointer merely falls back to a\n    // fresh conversation when the next scheduled run starts.\n    if (execution.sessionReuseMode !== 'fresh' && typeof rawExecution.autoReuseSessionId === 'string'\n      && rawExecution.autoReuseSessionId.length > 0 && rawExecution.autoReuseSessionId.length <= 256) {\n      execution.autoReuseSessionId = rawExecution.autoReuseSessionId\n      if (typeof rawExecution.autoReuseSessionKey === 'string' && rawExecution.autoReuseSessionKey.length <= 1024) {\n        execution.autoReuseSessionKey = rawExecution.autoReuseSessionKey\n      }\n    }\n    // Queue markers are scheduler-owned, but must survive export/import: an\n    // online-and-queued window is not equivalent to an offline missed window.\n    const queuedWindow = typeof rawExecution.queuedRunAt === 'number' && Number.isFinite(rawExecution.queuedRunAt)\n      ? rawExecution.queuedRunAt\n      : typeof r